INSERT INTO "citation_mining" ("slug", "local_ref_id", "global_ref_id", "doi", "backward", "forward", "connections_produced", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "deferred_reason") VALUES ('accessible-circulation-geometry', 'ES-03', 'REF-01029', NULL, 1, 0, NULL, '[backward 2026-10-01 03:41] Pass RAN in part. The Metodología''s legislation list (pp. 5-6) and its p. 24 tiers point to Orden VIV/561/2010 (retrieved this batch from BOE; found DEROGATED 2022-01-02, staged as candidate OUT-OF-SCOPE) and to the CTE (retrieved as REF-01027). NOT chased: RD 505/2007, Orden PRE/446/2008, Manual de Accesibilidad de Espacios Públicos Urbanizados 2016 (Ayuntamiento de Madrid), Comunidad de Madrid Decreto 13/2007.', '2026-10-01 03:41', 'session_2026-10-01-research-batch-23', '2026-10-01 03:41', 'session_2026-10-01-research-batch-23', NULL);
INSERT INTO "citation_mining" ("slug", "local_ref_id", "global_ref_id", "doi", "backward", "forward", "connections_produced", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "deferred_reason") VALUES ('accessible-circulation-geometry', 'NL-03', 'REF-01022', NULL, 1, 0, NULL, '[backward 2026-10-01 03:40] Pass RAN by reading the letter in full (2 pp.). It cites no source, bibliography or figure. Its only external referents are the Verzamelbesluit Bbl 2024 (retrieved this batch as Stb. 2024, 368 = REF-01020) and NEN 9120 (a draft Dutch standard, the national elaboration of EN 17210; paywalled and filed as a research_code_leads row). Nothing further to chase.', '2026-10-01 03:40', 'session_2026-10-01-research-batch-23', '2026-10-01 03:40', 'session_2026-10-01-research-batch-23', NULL);
INSERT INTO "citation_mining" ("slug", "local_ref_id", "global_ref_id", "doi", "backward", "forward", "connections_produced", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "deferred_reason") VALUES ('accessible-circulation-geometry', 'SE-03', 'REF-01025', NULL, 1, 0, NULL, '[backward 2026-10-01 03:41] Pass RAN by reading the 7-page reply. It cites only section numbers of Boverket''s draft revision of the BBR (sections 3 and 8, 2007), not a retrievable bibliography; the criticised provision (BBR 3:1222, 1:12) is the ancestor of BFS 2024:12 2 kap. 4 § (REF-01023). The 2007 BBR revision text itself was not retrieved.', '2026-10-01 03:41', 'session_2026-10-01-research-batch-23', '2026-10-01 03:41', 'session_2026-10-01-research-batch-23', NULL);
