INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-058', 'SW', 'P2', 'OPEN', 'research-batch', 'scripts/db.py add_source / link_source_slug', 'add-source HALF-WRITES BEFORE IT REFUSES, AND THE ONE VERB THAT COULD REPAIR IT REFUSES TOO. Found filing batch 23 (session_2026-10-01-research-batch-23). Run without --local-ref-id into accessible-circulation-geometry, add-source printed ''REFUSING: slug ... already mixes local_ref_id label schemes (10, 11, ...); a derived label cannot be trusted to match'' and exited non-zero -- but the evidence_sources row and its evidence_source_authors rows were ALREADY INSERTED (3 of 3 calls: REF-01019 to REF-01021 existed afterwards, with no source_slug_links row). The refusal text implies nothing was written; a retry with --local-ref-id then fails ''REF-0101x already exists (R9)''. link-source-slug, the sanctioned way to attach an existing source to a slug, takes --rationale but no label and refuses on the same mixed-scheme check, so there is no sanctioned repair. Cleared in the SCRATCH copy only (rows deleted before capture, re-added with explicit labels). Two defects: (1) the slug-link validity check runs after the INSERT instead of before it, or the INSERT is not in the same transaction; (2) link-source-slug cannot be told a label. UNDERLYING CAUSE: the slug''s local_ref_id scheme is mixed (numeric 10-32 from batches up to 22, then jurisdiction labels IE-01, FI-01, NZ-01 from batch 22) -- a derived label is refused, so every add-source into this slug needs an explicit --local-ref-id until the scheme is reconciled. FIX (tooling-only PR, rule 10): run the link check before any write, in one transaction; give link-source-slug a --local-ref-id; reconcile or document the label scheme. A one-line test: add-source into this slug with no --local-ref-id must leave the DB byte-identical.', '2026-10-01 03:09', 'session_2026-10-01-research-batch-23', '2026-10-01 03:09', 'session_2026-10-01-research-batch-23', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-059', 'SW', 'P3', 'OPEN', 'research-batch', 'scripts/db.py resolve-candidate / add-candidate', 'NO SANCTIONED WRITER RAISES harm_finding ON AN EXISTING search_candidates ROW. Found by batch 23''s adversarial pass (S1): exec 171''s CERMI Madrid retrieval carries harm_finding=1 (the Metodología''s p. 10 statement that slopes above 6% are seriously difficult and above 10% impracticable), but candidate 132, resolved to REF-01029 by this session, still reads harm_finding=0, whereas candidates 124 and 129 (REF-01007, REF-01011) carry the flag. add-candidate takes --harm-finding only at creation; resolve-candidate (disposition, redescription, admitted ref, suggested slug) cannot raise it; amend-search''s --set-harm-finding is for search_executions only, and evidence_sources / source_value_extractions have no harm column at all, so for admitted sources the flag lives on the exec row and in free text (extractions 93, 102, 104 carry it only in notes). FIX (tooling-only PR, rule 10): add --set-harm-finding to resolve-candidate or an amend-candidate verb, raise-only as amend-search does; decide whether an extraction-level harm flag is wanted at all (S1 lens). Meanwhile the flag is recorded on the exec rows 157 (FUB), 164 (DHUP guide) and 171 (CERMI).', '2026-10-01 03:42', 'session_2026-10-01-research-batch-23', '2026-10-01 03:42', 'session_2026-10-01-research-batch-23', NULL, NULL, NULL, NULL, NULL);
