INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (129, 'accessible-circulation-geometry', 'KR', 'KO', NULL, 'code', NULL, '편의증진 보장에 관한 법률 시행규칙 별표 1 경사로 기울기 1/12 이하 편의시설의 구조 재질 세부기준', NULL, 'web', 'scoping', NULL, 9, 9, 0, 'none', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:05', 'WEB-SEARCH SUMMARY CONTRADICTED BY THE BYTES LATER RETRIEVED: the tool''s summary said ''approach path gradient 1/18 or less, relaxed to 1/12 where terrain is difficult'' under the ramp question. That is item 1 of Annex 1 (접근로, approach path); the RAMP (경사로) item is item 12 and reads 12분의 1 or less. The conflation is the hazard here, so it is recorded. Hits were one legal-wiki page (NEPLA), several installer-marketplace pages (qnaqc, soomgo) and a 1997 press item; no official host in the list.', 0, 'Korea''s accessibility law enforcement rule (장애인ㆍ노인ㆍ임산부 등의 편의증진 보장에 관한 법률 시행규칙 별표 1) sets a ramp gradient of 1/12 or less, with a relaxed ~1/8 allowance where terrain forbids; expect the text on law.go.kr (a JS-heavy site, so retrieval may be the hard part, not the value).', 'planned', NULL, NULL, '2026-10-01 03:05', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (130, 'accessible-circulation-geometry', 'KR', 'EN', NULL, 'code', NULL, 'Enforcement Rule of the Act on Guarantee of Promotion of Convenience of Persons with Disabilities, the Elderly and Pregnant Women Annex 1 ramp slope 1/12 elaw.klri.re.kr', NULL, 'web', 'scoping', NULL, 10, 10, 0, 'none', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:05', 'WRONG INDEX / TRANSLATION NOT FOUND, NOT ABSENCE OF THE RULE: elaw.klri.re.kr listed the Act and decrees (hseq 53020, 46425 retrieved this session and identified as Acts on welfare of persons with disabilities / prohibition of discrimination, not the Enforcement Rule). No English translation of the Enforcement Rule''s Annex 1 was located. Results otherwise were ADA material. || CORRECTED 2026-10-01: PRIOR DISCLOSURE (adversarial pass F4): this row''s prior_expectation was COMPOSED AT LOGGING TIME, after the search or fetch had been run and its result read; it describes what was then expected given the preceding result and is NOT a pre-registered prior. Only the first-search priors for KR, SG, PT, EU, FR, ES, NL, SE, AU and the Korean Co-1 query were written before any search ran (priors.txt, written 02:36:01 UTC; first WebSearch about 02:36:03 UTC). All search rows of this batch were logged after the fact, in one pass.', 0, 'Expect the KLRI English translation (elaw.klri.re.kr) to carry the Enforcement Rule with its Annex 1 ramp clause, as it does for many Korean statutes; the prior for KR is otherwise as logged for the first KR search.', 'planned', NULL, NULL, '2026-10-01 03:42', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (131, 'accessible-circulation-geometry', 'KR', 'KO', NULL, 'code', NULL, '장애인·노인·임산부 등의 편의증진 보장에 관한 법률 시행규칙 [별표 1] 편의시설의 구조·재질 등에 관한 세부기준 경사로 기울기 1/12 법령 전문', NULL, 'web', 'scoping', NULL, 8, 8, 0, 'none', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:05', 'Surfaced the NEPLA wiki page (a mirror of Annex 1 with the amendment stamp) and a Seoul facilities manual hosted on nld.go.kr; official law.go.kr not in the list. || CORRECTED 2026-10-01: PRIOR DISCLOSURE (adversarial pass F4): this row''s prior_expectation was COMPOSED AT LOGGING TIME, after the search or fetch had been run and its result read; it describes what was then expected given the preceding result and is NOT a pre-registered prior. Only the first-search priors for KR, SG, PT, EU, FR, ES, NL, SE, AU and the Korean Co-1 query were written before any search ran (priors.txt, written 02:36:01 UTC; first WebSearch about 02:36:03 UTC). All search rows of this batch were logged after the fact, in one pass.', 0, 'Expect the second, fuller phrasing to surface the rule text on law.go.kr or a faithful mirror; if only mirrors, the value 1/12 should still appear verbatim.', 'planned', NULL, NULL, '2026-10-01 03:42', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (132, 'accessible-circulation-geometry', 'KR', 'KO', NULL, 'code', NULL, 'https://www.nepla.ai/wiki/복지와-건강/사회복지/-유권해석-장애인-노인-임산부-등의-편의증진-보장에-관한-법률-시행규칙-별표-1-편의시설의-구조·재질등에-관한-세부기준-제2조제1항관련-1509xgx0mnol', NULL, 'web', 'scoping', NULL, 1, 1, 1, 'saturated', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:05', 'RETRIEVED, 200, 172 kB HTML. Annex 1 text under the stamp <개정 2023. 12. 11.>. Item 12 나목: (1) 경사로 기울기 12분의 1 이하 (''하여야 한다''); (2) relaxable to 8분의 1 only if the ramp is in an EXISTING facility, height <= 1 m, 1/12 structurally difficult, AND the facility manager provides continuous assistance (상시보조서비스). Item 1 나목(1): 접근로 18분의 1 or less, relaxable to 12분의 1 where terrain is difficult (NOT a ramp; not extracted). The page''s 비고 says ''…할 수 있다'' items are recommendations. Mirror, not the official host; issuing ministry not stated. Admitted GREY/UNVERIFIED as REF-01019. || CORRECTED 2026-10-01: PRIOR DISCLOSURE (adversarial pass F4): this row''s prior_expectation was COMPOSED AT LOGGING TIME, after the search or fetch had been run and its result read; it describes what was then expected given the preceding result and is NOT a pre-registered prior. Only the first-search priors for KR, SG, PT, EU, FR, ES, NL, SE, AU and the Korean Co-1 query were written before any search ran (priors.txt, written 02:36:01 UTC; first WebSearch about 02:36:03 UTC). All search rows of this batch were logged after the fact, in one pass.', 0, 'Follow-up direct retrieval of the NEPLA mirror found by the preceding search: expect Annex 1 in full with 12분의 1 for 경사로 (item 12) and 18분의 1 for 접근로 (item 1).', 'planned', NULL, NULL, '2026-10-01 03:42', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (133, 'accessible-circulation-geometry', 'KR', 'KO', NULL, 'code', NULL, 'https://www.law.go.kr/법령/장애인ㆍ노인ㆍ임산부등의편의증진보장에관한법률시행규칙', NULL, 'web', 'scoping', NULL, 0, 0, 0, 'none', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:05', 'RETRIEVAL FAILURE, NOT ABSENCE: curl exit 35 (connection reset by peer) on the law page and on the DRF OpenAPI search URL; nld.go.kr (Seoul manual) answered 400 ''Request Blocked''. Consistent with geo-filtering of foreign cloud addresses; not confirmed. These attempts were made outside retrieval_log.fetch (curl probes) and are therefore NOT in the manifest -- recorded here only. || CORRECTED 2026-10-01: PRIOR DISCLOSURE (adversarial pass F4): this row''s prior_expectation was COMPOSED AT LOGGING TIME, after the search or fetch had been run and its result read; it describes what was then expected given the preceding result and is NOT a pre-registered prior. Only the first-search priors for KR, SG, PT, EU, FR, ES, NL, SE, AU and the Korean Co-1 query were written before any search ran (priors.txt, written 02:36:01 UTC; first WebSearch about 02:36:03 UTC). All search rows of this batch were logged after the fact, in one pass. || CORRECTED 2026-10-01: CORRECTION (repair phase): the official host is reachable at a DIFFERENT law.go.kr endpoint. www.law.go.kr/LSW/flDownload.do?flSeq=162983711 serves the Enforcement Rule''s Annex 1 as a 22-page PDF (retrieved, admitted as REF-01031); only the law PAGE URL and the DRF OpenAPI URL reset the connection. ''Retrieval failure'' above stands for those two URLs only.', 0, 'Expect the official Korean legal-information host (law.go.kr) to serve the Enforcement Rule; it is a dynamic site, so retrieval, not the value, is the risk.', 'planned', NULL, NULL, '2026-10-01 03:42', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (134, 'accessible-circulation-geometry', 'KR', 'KO', 1, 'co1', NULL, '휠체어 이용자 장애인 당사자 경사로 기울기 12분의 1 너무 가파르다 장애인단체 경사로 기준 개선 요구', NULL, 'web', 'scoping', NULL, 9, 9, 0, 'none', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:05', 'ZERO CO-1 YIELD, AND NOT CONCLUSIVE ABSENCE (R14): the query is a long Korean multi-concept phrasing run on a general web index; the nine hits were an IT-Q&A page and installer-marketplace pages (soomgo). The tool summary itself said it found no disability-organisation demand about 1/12. No Korean DPO repository (e.g. a disability-organisation site search) was queried, so this is wrong-index / query-shape, not genuine absence.', 0, 'a Korean-language lived-experience query (''wheelchair user ramp slope DPO testimony'') will mostly return news/vendor pages; expect null or near-null on any DPO-authored gradient position.', 'planned', NULL, NULL, '2026-10-01 03:05', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (135, 'accessible-circulation-geometry', 'SG', 'EN', NULL, 'code', NULL, 'BCA Code on Accessibility in the Built Environment 2019 ramp gradient maximum 1:12 Singapore', NULL, 'web', 'scoping', NULL, 9, 9, 0, 'none', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:05', 'Surfaced the BCA Code PDF (www1.bca.gov.sg/docs/default-source/universaldesign/accessibilitycode2019.pdf), the BCA Code page, a 2018 REACH consultation DRAFT, a 2025 BCA consultation circular and Philippine BP 344 material. The tool summary said the gradient was ''not visible in the excerpt''. No value taken from any summary.', 0, 'BCA Code on Accessibility in the Built Environment (2019) sets ramp gradient 1:12 max with rise/landing limits; expect a PDF on bca.gov.sg or a mirror; possibly gated by a bot-challenge.', 'planned', NULL, NULL, '2026-10-01 03:05', 'session_2026-10-01-research-batch-23');
