INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (137, 'accessible-circulation-geometry', 'SG', 'EN', NULL, 'code', NULL, 'Singapore accessibility code 2019 ramp gradient not steeper than 1:12 landing wheelchair BCA Universal Design Guide ramp slope', NULL, 'web', 'scoping', NULL, 9, 9, 0, 'none', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:05', 'Nothing restating the clause from a reachable host; fliphtml5 and ncda.gov.ph hits concern the Philippines. GENUINE NO-MIRROR FINDING for the reachable index. || CORRECTED 2026-10-01: PRIOR DISCLOSURE (adversarial pass F4): this row''s prior_expectation was COMPOSED AT LOGGING TIME, after the search or fetch had been run and its result read; it describes what was then expected given the preceding result and is NOT a pre-registered prior. Only the first-search priors for KR, SG, PT, EU, FR, ES, NL, SE, AU and the Korean Co-1 query were written before any search ran (priors.txt, written 02:36:01 UTC; first WebSearch about 02:36:03 UTC). All search rows of this batch were logged after the fact, in one pass.', 0, 'Expect secondary Singapore pages (agency or consultant guides) restating the ramp gradient.', 'planned', NULL, NULL, '2026-10-01 03:42', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (138, 'accessible-circulation-geometry', 'SG', 'EN', NULL, 'code', NULL, 'https://www1.bca.gov.sg/docs/default-source/universaldesign/accessibilitycode2019.pdf', NULL, 'web', 'scoping', NULL, 0, 0, 0, 'none', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:05', 'RETRIEVAL FAILURE, NOT ABSENCE: HTTP 403 (919-byte interstitial) on the PDF, on the BCA Code page, on the REACH 2018 draft and on the 2025 consultation circular (four 403 artefacts persisted in this session''s manifest). Wayback: archive.org/wayback/available lists a 2026-01-14 snapshot, but replay on web.archive.org failed twice (curl exit 35; the proxy status shows ws_closed_mid_exchange for web.archive.org:443) in both the if_ and plain /web/<ts>/ forms -- the same session-level limit batch 22 recorded for CSA B651. Nothing admitted; SG stays searched with NO retrievable text. || CORRECTED 2026-10-01: PRIOR DISCLOSURE (adversarial pass F4): this row''s prior_expectation was COMPOSED AT LOGGING TIME, after the search or fetch had been run and its result read; it describes what was then expected given the preceding result and is NOT a pre-registered prior. Only the first-search priors for KR, SG, PT, EU, FR, ES, NL, SE, AU and the Korean Co-1 query were written before any search ran (priors.txt, written 02:36:01 UTC; first WebSearch about 02:36:03 UTC). All search rows of this batch were logged after the fact, in one pass.', 0, 'Expect the official BCA PDF to download; bot-challenge gating was the logged risk in the SG prior.', 'planned', NULL, NULL, '2026-10-01 03:42', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (139, 'accessible-circulation-geometry', 'PT', 'PT', NULL, 'code', NULL, 'Decreto-Lei 163/2006 acessibilidades rampas inclinação máxima anexo normas técnicas', NULL, 'web', 'scoping', NULL, 9, 9, 0, 'none', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:05', 'Surfaced an Ordem dos Arquitectos PDF of the decree, municipal slide decks, an LNEC repository file and architect blogs. Tool summary: sidewalks and routes 6% longitudinal max; ramp specifics ''in the annex''. Nothing taken from the summary.', 0, 'Decreto-Lei 163/2006 Anexo gives ramp gradient as a tiered % table by length/height (about 6% general rising to 8% and 10% for short runs); expect Diario da Republica / a mirror PDF; value shape tiered, not single.', 'planned', NULL, NULL, '2026-10-01 03:05', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (140, 'accessible-circulation-geometry', 'PT', 'PT', NULL, 'code', NULL, 'https://ordemdosarquitectos.org/backend/uploads/decretolei_163_2006_a8acccc42f.pdf', NULL, 'web', 'scoping', NULL, 1, 1, 1, 'saturated', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:05', 'RETRIEVED, 200, 651 kB PDF, 41 pp. Page 1 says it TRANSCRIBES the decree and ''não substitui a consulta da sua publicação em Diário da República''. Anexo 2.5.1: <=6% with rise <=0.6 m and projection <=10 m, or <=8% with rise <=0.4 m and projection <=5 m, interpolated values permitted; 2.5.2 (alteration of existing buildings only): 10% (rise <=0.2 m, projection <=2 m) or 12% (rise <=0.1 m, projection <=0.83 m). Admitted GREY/UNVERIFIED as REF-01026 (transcription, not the DR original). || CORRECTED 2026-10-01: PRIOR DISCLOSURE (adversarial pass F4): this row''s prior_expectation was COMPOSED AT LOGGING TIME, after the search or fetch had been run and its result read; it describes what was then expected given the preceding result and is NOT a pre-registered prior. Only the first-search priors for KR, SG, PT, EU, FR, ES, NL, SE, AU and the Korean Co-1 query were written before any search ran (priors.txt, written 02:36:01 UTC; first WebSearch about 02:36:03 UTC). All search rows of this batch were logged after the fact, in one pass.', 0, 'Follow-up direct retrieval: expect the decree text including Anexo 2.5 Rampas with a tiered percentage table by rise and run.', 'planned', NULL, NULL, '2026-10-01 03:42', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (141, 'accessible-circulation-geometry', 'PT', 'PT', NULL, 'code', NULL, 'Decreto-Lei n.º 163/2006 de 8 de agosto Diário da República 1.ª série-A n.º 152 acessibilidade texto original files.diariodarepublica.pt', NULL, 'web', 'scoping', NULL, 9, 9, 0, 'none', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:05', 'Surfaced diariodarepublica.pt consolidated legislation, vlex and municipal copies. Retrieval of the DRE page returned HTTP 200 but only a 2.3 kB ''JavaScript is required'' shell (artefact 0794abe5f8088cfd.html): NO TEXT. The transcription therefore stays UNVERIFIED against the original. || CORRECTED 2026-10-01: PRIOR DISCLOSURE (adversarial pass F4): this row''s prior_expectation was COMPOSED AT LOGGING TIME, after the search or fetch had been run and its result read; it describes what was then expected given the preceding result and is NOT a pre-registered prior. Only the first-search priors for KR, SG, PT, EU, FR, ES, NL, SE, AU and the Korean Co-1 query were written before any search ran (priors.txt, written 02:36:01 UTC; first WebSearch about 02:36:03 UTC). All search rows of this batch were logged after the fact, in one pass.', 0, 'Expect the official Diario da Republica to carry the decree and let the transcription be checked against it.', 'planned', NULL, NULL, '2026-10-01 03:42', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (142, 'accessible-circulation-geometry', 'EU', 'EN', 4, 'standard_eb', NULL, 'EN 17210:2021 accessibility and usability of the built environment ramp gradient requirement', NULL, 'web', 'scoping', NULL, 10, 10, 0, 'none', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:05', 'THE TOOL SUMMARY ASSERTED ''Clause 7.5: max gradient 1:12 for rises up to 500 mm and 1:20 for longer ramps, 1500 mm landings every 10 m''. NOT USED. A CEN/CLC JTC 11 workshop deck retrieved from UNE (below) lists the standard''s chapters and puts ramps under chapter 10 ''Vertical circulation'', not 7 (''Access in the outdoor environment'') -- so the summary''s clause number is contradicted by the one primary-adjacent artefact obtained. No clause text of EN 17210 is freely available in the result list (BSI, Genorma, UNE catalogue pages).', 0, 'EN 17210:2021 (CEN) is the pan-European accessibility-of-built-environment standard; expect it to be paywalled with no free clause text, so the search will yield catalogue/preview pages and a lead, not a primary value.', 'planned', NULL, NULL, '2026-10-01 03:05', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (143, 'accessible-circulation-geometry', 'EU', 'EN', NULL, 'standard_eb', NULL, 'https://www.une.org/normalizacion_documentos/PT%20EN%2017210.pdf', NULL, 'web', 'scoping', NULL, 1, 1, 0, 'partial', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:05', 'RETRIEVED, 200, 1.96 MB, 18 slides: ''Towards common European criteria on accessibility of the built environment: Outcomes of Mandate M/420'' (CEN/CLC JTC 11, 22 March 2021). Contents only: chapter 10 ''Vertical circulation (ramps, stairs, handrails, lifts, escalators)''. NO gradient value. Not admitted. EU therefore stays SEARCHED / PAYWALLED: lead filed for EN 17210:2021. The Dutch Bbl nota (REF-01020) says the new Dutch small-rise tiers come from NEN 9120, the Dutch elaboration of EN 17210 -- the only route by which an EN 17210 figure is visible in this corpus. || CORRECTED 2026-10-01: Linked a derived visible-text extraction (a426a8c5ff9b197e-text.txt) alongside the persisted original, so a candidate row can quote it (the PDF/HTML itself is not quote-decodable for add-candidate''s checker). || CORRECTED 2026-10-01: result artefact(s) added: retrieval-log/session_2026-10-01-research-batch-23/a426a8c5ff9b197e-text.txt || CORRECTED 2026-10-01: PRIOR DISCLOSURE (adversarial pass F4): this row''s prior_expectation was COMPOSED AT LOGGING TIME, after the search or fetch had been run and its result read; it describes what was then expected given the preceding result and is NOT a pre-registered prior. Only the first-search priors for KR, SG, PT, EU, FR, ES, NL, SE, AU and the Korean Co-1 query were written before any search ran (priors.txt, written 02:36:01 UTC; first WebSearch about 02:36:03 UTC). All search rows of this batch were logged after the fact, in one pass.', 0, 'Follow-up: expect the UNE preview file to carry catalogue or scope pages only, possibly the table of contents.', 'planned', NULL, NULL, '2026-10-01 03:42', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (144, 'accessible-circulation-geometry', 'NL', 'NL', NULL, 'code', NULL, 'Besluit bouwwerken leefomgeving hellingbaan toegankelijkheid helling ten hoogste 1:12 rolstoel wetten.overheid.nl', NULL, 'web', 'scoping', NULL, 10, 10, 0, 'none', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:05', 'Tool summary gave 1:12 (<=0.25 m rise), 1:16 (<=0.5 m), 1:20 (>0.5 m): that is the PRE-1-JULY-2025 table. The retrieved IPLO page and Staatsblad show two further tiers below 1:12 (1:6, 1:10) in force since 2025-07-01. Hits: IPLO, inview.nl, omgevingsweb.nl, a BZK infographic.', 0, 'Bouwbesluit 2012 / Besluit bouwwerken leefomgeving (Bbl) gives a hellingbaan (''ramp'') gradient limit near 1:12 with a separate rule for small rises; expect wetten.overheid.nl to be retrievable.', 'planned', NULL, NULL, '2026-10-01 03:05', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (145, 'accessible-circulation-geometry', 'NL', 'NL', NULL, 'code', NULL, 'Besluit bouwwerken leefomgeving artikel 4.30 hellingbaan "hoogteverschil" helling tabel wetten.overheid.nl BWBR0041297', NULL, 'web', 'scoping', NULL, 9, 9, 0, 'none', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:05', 'wetten.overheid.nl NOT RETRIEVABLE from here: curl exit 92 (HTTP/2 PROTOCOL_ERROR) then exit 52 (empty reply) over HTTP/1.1; inview.nl art. 4.30 answered 403 (118-byte body). So the legal text of art. 4.30 itself was not obtained; the amendment text was, from the Staatsblad. || CORRECTED 2026-10-01: PRIOR DISCLOSURE (adversarial pass F4): this row''s prior_expectation was COMPOSED AT LOGGING TIME, after the search or fetch had been run and its result read; it describes what was then expected given the preceding result and is NOT a pre-registered prior. Only the first-search priors for KR, SG, PT, EU, FR, ES, NL, SE, AU and the Korean Co-1 query were written before any search ran (priors.txt, written 02:36:01 UTC; first WebSearch about 02:36:03 UTC). All search rows of this batch were logged after the fact, in one pass.', 0, 'Expect wetten.overheid.nl art. 4.30 text to be reachable and to carry the current tiers.', 'planned', NULL, NULL, '2026-10-01 03:42', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (146, 'accessible-circulation-geometry', 'NL', 'NL', NULL, 'code', NULL, 'Staatsblad 2025 wijziging Besluit bouwwerken leefomgeving artikel 4.30 hellingbaan 1:6 1:10 NEN 9120 verzamelbesluit zoek.officielebekendmakingen.nl', NULL, 'web', 'scoping', NULL, 9, 9, 0, 'none', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:05', 'Surfaced Stb. 2025, 432 (retrieved: a DIFFERENT decree, of 4 Dec 2025, on environmental-performance requirements -- screened out, not ramp-relevant) and, by the tool''s text, Stb. 2024, 368 as the carrier of the July 2025 art. 4.30 change. Direct retrieval of Stb. 2024, 368 follows. || CORRECTED 2026-10-01: PRIOR DISCLOSURE (adversarial pass F4): this row''s prior_expectation was COMPOSED AT LOGGING TIME, after the search or fetch had been run and its result read; it describes what was then expected given the preceding result and is NOT a pre-registered prior. Only the first-search priors for KR, SG, PT, EU, FR, ES, NL, SE, AU and the Korean Co-1 query were written before any search ran (priors.txt, written 02:36:01 UTC; first WebSearch about 02:36:03 UTC). All search rows of this batch were logged after the fact, in one pass.', 0, 'Expect the official gazette (officielebekendmakingen.nl) to carry the amending decree and its explanatory note.', 'planned', NULL, NULL, '2026-10-01 03:42', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (147, 'accessible-circulation-geometry', 'NL', 'NL', NULL, 'code', NULL, 'https://zoek.officielebekendmakingen.nl/stb-2024-368.pdf', NULL, 'web', 'scoping', NULL, 1, 1, 1, 'saturated', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:05', 'RETRIEVED, 200, 448 kB, 39 pp. Besluit van 25 november 2024. Art. I onderdeel R / art. 4.30 lid 2: a. 1:6 if rise <=0.05 m; b. 1:10 if >0.05 and <=0.10 m; c. 1:12 if >0.10 and <=0.25 m (the former a-c re-lettered c-e, so 1:16 and 1:20 are unchanged text not reproduced). Art. II lid 2: onderdeel R in force 1 July 2025. Nota: the added dimensions are taken over from NEN 9120, ''Nederlandse uitwerking van NEN-EN 17210'', in development; the nota writes ''mm'' where the operative text is metres (slip, flagged). Admitted as REF-01020. || CORRECTED 2026-10-01: PRIOR DISCLOSURE (adversarial pass F4): this row''s prior_expectation was COMPOSED AT LOGGING TIME, after the search or fetch had been run and its result read; it describes what was then expected given the preceding result and is NOT a pre-registered prior. Only the first-search priors for KR, SG, PT, EU, FR, ES, NL, SE, AU and the Korean Co-1 query were written before any search ran (priors.txt, written 02:36:01 UTC; first WebSearch about 02:36:03 UTC). All search rows of this batch were logged after the fact, in one pass.', 0, 'Expect the Verzamelbesluit Bbl 2024 to contain onderdeel R amending art. 4.30 with new small-rise slope tiers and an explanatory note naming their source.', 'planned', NULL, NULL, '2026-10-01 03:42', 'session_2026-10-01-research-batch-23');
