INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (153, 'accessible-circulation-geometry', 'SE', 'SV', NULL, 'code', NULL, 'https://www.varberg.se/download/18.2b514d9b18a92e6fafc230fb/1387272663974/BFS2011-5-ALM2.pdf', NULL, 'web', 'scoping', NULL, 1, 1, 0, 'saturated', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:05', 'RETRIEVED, 200, 48 kB, 8 pp. Title page: Boverkets författningssamling BFS 2011:5 ALM 2, ''Utkom från trycket den 26 april 2011''. 9 §, Allmänt råd: ''En ramp bör luta högst 1:20 mellan minst 2 meter långa vilplan'', rise <=0.5 m between landings; 8 §, Allmänt råd: ''En utjämning till 0-nivå bör inte ha större lutning än 1:12''. ADVICE (''bör''), not binding. Copy hosted by a municipality; Boverket''s page confirms the instrument. Admitted as REF-01024. || ADMISSION UNLINKED 2026-10-01 by session_2026-10-01-research-batch-23: REF-01024: Adversarial-pass repair F2: REF-01024 is re-filed as T5 national_fw (both extracted figures are Allmänt råd, i.e. advice; tier-system.md T5 names Boverket advisories); the T6 code row is withdrawn before capture and re-added under the same ref_id; the admission edge is re-recorded on a new exec. results_admitted 1 -> 0. || CORRECTED 2026-10-01: PRIOR DISCLOSURE (adversarial pass F4): this row''s prior_expectation was COMPOSED AT LOGGING TIME, after the search or fetch had been run and its result read; it describes what was then expected given the preceding result and is NOT a pre-registered prior. Only the first-search priors for KR, SG, PT, EU, FR, ES, NL, SE, AU and the Korean Co-1 query were written before any search ran (priors.txt, written 02:36:01 UTC; first WebSearch about 02:36:03 UTC). All search rows of this batch were logged after the fact, in one pass.', 0, 'Follow-up: expect ALM 2 to state the public-places ramp advice 1:20 as general advice (allmänt råd), not as a binding föreskrift.', 'planned', NULL, NULL, '2026-10-01 03:42', 'session_2026-10-01-research-batch-23');
