INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (157, 'accessible-circulation-geometry', 'SE', 'SV', NULL, 'co1', NULL, 'https://www.fub.se/files/bilagor/b8_fs_1-07_boverket.pdf', NULL, 'web', 'scoping', NULL, 1, 1, 1, 'saturated', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:05', 'RETRIEVED, 200, 105 kB, 7 pp., Stockholm 2007-01-10, signed by the kanslichef. Point 3:1222: ''En ramplutning på 1:12 är en säkerhetsrisk. Det kräver kraft i armarna och stor manöverskicklighet för att inte rullstolen ska rulla bakåt och välta'' and a request that the maximum be 1:20 or a lift be required. R7 HARM FINDING. The ceiling stayed 1:12 until BFS 2024:12. Admitted T3 grey (Co-1 not claimed: wheelchair-user authorship not evidenced, D-0178) as REF-01025. || CORRECTED 2026-10-01: target_evidence_type grey -> co1: this follow-up retrieved a candidate surfaced by a Co-1-channel search (disability-sector organisation output); ''grey'' was the tier it was later ADMITTED at (T3), not what it was aimed at, and labelling a Swedish/Spanish search ''grey'' reads as the language-based down-tiering R5 forbids. The admitted tier stays T3 grey: Co-1 provenance is not evidenced in the bytes (D-0178). || CORRECTED 2026-10-01: target_evidence_type ''grey'' -> ''co1'' (misclassification corrected; the replaced value is kept here because the column no longer holds it) || CORRECTED 2026-10-01: PRIOR DISCLOSURE (adversarial pass F4): this row''s prior_expectation was COMPOSED AT LOGGING TIME, after the search or fetch had been run and its result read; it describes what was then expected given the preceding result and is NOT a pre-registered prior. Only the first-search priors for KR, SG, PT, EU, FR, ES, NL, SE, AU and the Korean Co-1 query were written before any search ran (priors.txt, written 02:36:01 UTC; first WebSearch about 02:36:03 UTC). All search rows of this batch were logged after the fact, in one pass. || CORRECTED 2026-10-01: R5 RETARGET DISCLOSURE (adversarial pass F9): the grey -> co1 change above was made AFTER research_batch_dod R5 reported these execs. R5''s rationale concerns non-English PEER-REVIEWED work, and neither document is peer-reviewed, so the R5 failure was arguably a false positive and a reasoned waiver was the honest route; the edit was nonetheless gate-driven. The earlier Co-1-channel exec for each document had already recorded it as Co-1-ADJACENT (FUB) or as a Co-1 DPO-sector question (CERMI) before this fetch was logged.', 1, 'Follow-up: expect a remissvar that may comment on ramp gradient.', 'planned', NULL, NULL, '2026-10-01 03:42', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (158, 'accessible-circulation-geometry', 'SE', 'SV', NULL, 'code', NULL, 'BFS 2024:12 Boverkets föreskrifter om byggnaders tillgänglighet och användbarhet för personer med nedsatt rörelse- eller orienteringsförmåga pdf ikraftträdande', NULL, 'web', 'scoping', NULL, 9, 9, 0, 'none', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:05', 'Surfaced rinfo.boverket.se/BFS2024-12/pdf/BFS2024-12.pdf and Boverket comparison tables (BFS 2024:12 replaces the accessibility provisions of BBR BFS 2011:6). || CORRECTED 2026-10-01: PRIOR DISCLOSURE (adversarial pass F4): this row''s prior_expectation was COMPOSED AT LOGGING TIME, after the search or fetch had been run and its result read; it describes what was then expected given the preceding result and is NOT a pre-registered prior. Only the first-search priors for KR, SG, PT, EU, FR, ES, NL, SE, AU and the Korean Co-1 query were written before any search ran (priors.txt, written 02:36:01 UTC; first WebSearch about 02:36:03 UTC). All search rows of this batch were logged after the fact, in one pass.', 0, 'Expect the current Boverket regulation on building accessibility to carry the binding ramp gradient.', 'planned', NULL, NULL, '2026-10-01 03:42', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (159, 'accessible-circulation-geometry', 'SE', 'SV', NULL, 'code', NULL, 'https://rinfo.boverket.se/BFS2024-12/pdf/BFS2024-12.pdf', NULL, 'web', 'scoping', NULL, 1, 1, 1, 'saturated', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:05', 'RETRIEVED, 200, 224 kB, 9 pp. ''Utkom från trycket den 20 november 2024''. 2 kap. 4 §: ''En ramp, som är till för att uppfylla kraven enligt 1 § och 2 § andra stycket, ska luta högst 1:12.'' In force 1 July 2025 (older BBR provisions applicable only as BFS 2024:14 point 3 allows). Admitted as REF-01023. || CORRECTED 2026-10-01: PRIOR DISCLOSURE (adversarial pass F4): this row''s prior_expectation was COMPOSED AT LOGGING TIME, after the search or fetch had been run and its result read; it describes what was then expected given the preceding result and is NOT a pre-registered prior. Only the first-search priors for KR, SG, PT, EU, FR, ES, NL, SE, AU and the Korean Co-1 query were written before any search ran (priors.txt, written 02:36:01 UTC; first WebSearch about 02:36:03 UTC). All search rows of this batch were logged after the fact, in one pass.', 0, 'Follow-up: expect 2 kap. to set a binding maximum ramp gradient near 1:12.', 'planned', NULL, NULL, '2026-10-01 03:42', 'session_2026-10-01-research-batch-23');
