planned', NULL, NULL, '2026-10-01 03:42', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (161, 'accessible-circulation-geometry', 'FR', 'FR', NULL, 'code', NULL, 'arrêté du 20 avril 2017 accessibilité ERP neufs article 2 cheminement rampe pente 5 % 8 % 10 % texte officiel', NULL, 'web', 'scoping', NULL, 9, 9, 0, 'none', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:05', 'Surfaced prefecture PDFs of the arrêté (maine-et-loire.gouv.fr, drome.gouv.fr) and DDT notices. The tool summary refused to give the values and pointed to Légifrance. THE 5%/8%/10% IN THE QUERY WERE MY PRIOR, NOT A FINDING; none is asserted.', 0, 'Arrete du 20 avril 2017 art. 2 gives max ramp slope 5%, with exceptional 8% (<=2 m) and 10% (<=0.5 m) tolerances; Legifrance has returned 403 on every prior automated fetch (lead 86), so expect to need a different host (government ministry PDF or archive) for the same text.', 'planned', NULL, NULL, '2026-10-01 03:05', 'session_2026-10-01-research-batch-23');
