domain.', 'planned', NULL, NULL, '2026-10-01 03:42', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (163, 'accessible-circulation-geometry', 'FR', 'FR', NULL, 'code', NULL, 'arrêté 20 avril 2017 accessibilité ERP construction texte intégral article 2 cheminements rampe', NULL, 'web', 'scoping', NULL, 10, 10, 0, 'none', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:05', 'Domain-limited (ecologie.gouv.fr etc.) results: ministry guides (existing ERP, stations, commands) and the ERP accessibility page; no new-ERP arrêté text. The existing-ERP illustrated guide is the one document that reproduces ramp slope rules with their legal basis. || CORRECTED 2026-10-01: PRIOR DISCLOSURE (adversarial pass F4): this row''s prior_expectation was COMPOSED AT LOGGING TIME, after the search or fetch had been run and its result read; it describes what was then expected given the preceding result and is NOT a pre-registered prior. Only the first-search priors for KR, SG, PT, EU, FR, ES, NL, SE, AU and the Korean Co-1 query were written before any search ran (priors.txt, written 02:36:01 UTC; first WebSearch about 02:36:03 UTC). All search rows of this batch were logged after the fact, in one pass.', 0, 'Expect domain-limited search to surface ministry pages with the arrêté or its illustrated guide.', 'planned', NULL, NULL, '2026-10-01 03:42', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (164, 'accessible-circulation-geometry', 'FR', 'FR', NULL, 'national_fw', NULL, 'https://www.ecologie.gouv.fr/sites/default/files/publications/2019%2007%20guide_DHUP_erp-existants.pdf', NULL, 'web', 'scoping', NULL, 1, 1, 1, 'partial', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:05', 'RETRIEVED, 200, 9.6 MB, 65 pp. p. 12 reproduces ''Arrêté du 8 décembre 2014, Article 2'': slope <=6% for an inclined plane; tolerated exceptionally 10% over <=2 m and 12% over <=0.50 m; landing every 10 m from 5%. Margin commentary: ''À partir de 6 % sur plusieurs mètres, un nombre important de personnes en fauteuil roulant manuel vont perdre leur autonomie et devoir demander de l''aide''; recommends <=5%. R7 HARM FINDING. EXISTING-ERP REGIME ONLY. Admitted T5 as REF-01030. || CORRECTED 2026-10-01: PRIOR DISCLOSURE (adversarial pass F4): this row''s prior_expectation was COMPOSED AT LOGGING TIME, after the search or fetch had been run and its result read; it describes what was then expected given the preceding result and is NOT a pre-registered prior. Only the first-search priors for KR, SG, PT, EU, FR, ES, NL, SE, AU and the Korean Co-1 query were written before any search ran (priors.txt, written 02:36:01 UTC; first WebSearch about 02:36:03 UTC). All search rows of this batch were logged after the fact, in one pass.', 1, 'Follow-up: expect the DHUP illustrated guide to reproduce the existing-ERP arrêté of 8 December 2014 including ramp slopes.', 'planned', NULL, NULL, '2026-10-01 03:42', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (165, 'accessible-circulation-geometry', 'ES', 'ES', NULL, 'code', NULL, 'Código Técnico de la Edificación DB-SUA Seguridad de utilización y accesibilidad SUA 1 rampas pendiente 10% 8% 6% pdf codigotecnico.org', NULL, 'web', 'scoping', NULL, 9, 9, 0, 'none', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:05', 'Surfaced codigotecnico.org PDFs (DccSUA.pdf, DA_SUA_2) and consultant pages restating the 10/8/6 tiers (the lead-91 vendor restatements). The percentages in the query were my prior.', 0, 'CTE DB-SUA 9 (Accesibilidad) ramp slope tiered by length (<3 m 10%, <6 m 8%, else 6%); expect a codigotecnico.org PDF; lead 91 so far only vendor-restated.', 'planned', NULL, NULL, '2026-10-01 03:05', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (166, 'accessible-circulation-geometry', 'ES', 'ES', NULL, 'code', NULL, 'https://www.codigotecnico.org/pdf/Documentos/SUA/DccSUA.pdf', NULL, 'web', 'scoping', NULL, 1, 1, 1, 'saturated', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:05', 'RETRIEVED, 200, 1.68 MB, 79 pp. Ministerio de Vivienda y Agenda Urbana, DB-SUA ''con comentarios del Ministerio'', consolidated, version list ends 15 julio 2024. SUA 1 4.3.1(1): ramps 12% maximum, EXCEPT ramps on accessible itineraries: 10% if run <3 m, 8% if <6 m, 6% otherwise. Ministry comments are non-regulatory. Admitted as REF-01027; lead 91 (vendor-restated) is now confirmed against the primary. || CORRECTED 2026-10-01: PRIOR DISCLOSURE (adversarial pass F4): this row''s prior_expectation was COMPOSED AT LOGGING TIME, after the search or fetch had been run and its result read; it describes what was then expected given the preceding result and is NOT a pre-registered prior. Only the first-search priors for KR, SG, PT, EU, FR, ES, NL, SE, AU and the Korean Co-1 query were written before any search ran (priors.txt, written 02:36:01 UTC; first WebSearch about 02:36:03 UTC). All search rows of this batch were logged after the fact, in one pass.', 0, 'Follow-up: expect SUA 1 4.3.1 to state a general 12% ramp maximum and 10/8/6 tiers for accessible routes.', 'planned', NULL, NULL, '2026-10-01 03:42', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (167, 'accessible-circulation-geometry', 'ES', 'ES', NULL, 'code', NULL, 'Orden VIV/561/2010 artículo 14 rampas pendiente longitudinal máxima 10% menos de 3 m 8% BOE espacios públicos urbanizados', NULL, 'web', 'scoping', NULL, 9, 9, 0, 'none', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:05', 'THE TOOL SUMMARY SAID 8% UP TO 9 M; the BOE text of VIV/561/2010 says up to 10 m. More important, the BOE page of VIV/561/2010 (retrieved below) shows ''Fecha de derogación: 02/01/2022'' -- it is NO LONGER IN FORCE. || CORRECTED 2026-10-01: PRIOR DISCLOSURE (adversarial pass F4): this row''s prior_expectation was COMPOSED AT LOGGING TIME, after the search or fetch had been run and its result read; it describes what was then expected given the preceding result and is NOT a pre-registered prior. Only the first-search priors for KR, SG, PT, EU, FR, ES, NL, SE, AU and the Korean Co-1 query were written before any search ran (priors.txt, written 02:36:01 UTC; first WebSearch about 02:36:03 UTC). All search rows of this batch were logged after the fact, in one pass.', 0, 'CERMI Madrid cites Orden VIV/561/2010 for urban public spaces; expect art. 14 to give 10% to 3 m and 8% to 10 m and to be in force.', 'planned', NULL, NULL, '2026-10-01 03:42', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (168, 'accessible-circulation-geometry', 'ES', 'ES', NULL, 'code', NULL, 'Orden TMA/851/2021 de 23 de julio espacios públicos urbanizados rampas artículo pendiente longitudinal máxima boe.es', NULL, 'web', 'scoping', NULL, 10, 10, 0, 'none', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:05', 'Surfaced the BOE ELI pages of TMA/851/2021. The tool summary said the order''s maximum longitudinal slope is 6%: CONTRADICTED by the retrieved BOE text (6% is the definition threshold of a ramp, art. 14.1; the maximum is 10%/8% by run). || CORRECTED 2026-10-01: PRIOR DISCLOSURE (adversarial pass F4): this row''s prior_expectation was COMPOSED AT LOGGING TIME, after the search or fetch had been run and its result read; it describes what was then expected given the preceding result and is NOT a pre-registered prior. Only the first-search priors for KR, SG, PT, EU, FR, ES, NL, SE, AU and the Korean Co-1 query were written before any search ran (priors.txt, written 02:36:01 UTC; first WebSearch about 02:36:03 UTC). All search rows of this batch were logged after the fact, in one pass.', 0, 'Expect the successor order to carry the current urban-space ramp rule.', 'planned', NULL, NULL, '2026-10-01 03:42', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (169, 'accessible-circulation-geometry', 'ES', 'ES', NULL, 'code', NULL, 'https://www.boe.es/eli/es/o/2021/07/23/tma851/con', NULL, 'web', 'scoping', NULL, 1, 1, 1, 'saturated', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:05', 'RETRIEVED, 200, 154 kB, BOE núm. 187 of 06/08/2021, in force 02/01/2022 (BOE-A-2021-13488). Art. 14.2 c): 10% for runs up to 3.00 m, 8% for runs up to 9.00 m (horizontal projection); b): run capped at 9.00 m. Art. 14.1: a ramp is a plane above 6%. Admitted as REF-01028. || CORRECTED 2026-10-01: PRIOR DISCLOSURE (adversarial pass F4): this row''s prior_expectation was COMPOSED AT LOGGING TIME, after the search or fetch had been run and its result read; it describes what was then expected given the preceding result and is NOT a pre-registered prior. Only the first-search priors for KR, SG, PT, EU, FR, ES, NL, SE, AU and the Korean Co-1 query were written before any search ran (priors.txt, written 02:36:01 UTC; first WebSearch about 02:36:03 UTC). All search rows of this batch were logged after the fact, in one pass.', 0, 'Follow-up: expect art. 14 to keep the 2010 order structure with possible changes to the run cap.', 'planned', NULL, NULL, '2026-10-01 03:42', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (170, 'accessible-circulation-geometry', 'ES', 'ES', 1, 'co1', NULL, 'CERMI Comunidad de Madrid quiénes somos plataforma representativa entidades personas con discapacidad y sus familias', NULL, 'web', 'scoping', NULL, 9, 9, 0, 'none', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:05', 'Tool summary: constituted 1999 as a unitary platform of the Madrid federations ''representativas de personas con discapacidad'' (about 350 associations), mission to represent persons with disabilities AND their families. NOT retrieved as bytes (own site cermicomunidadmadrid.org closed the connection, curl exit 56), so it cannot evidence Co-1 provenance; the Metodología is therefore filed T3 grey, Co-1-adjacent. || CORRECTED 2026-10-01: PRIOR DISCLOSURE (adversarial pass F4): this row''s prior_expectation was COMPOSED AT LOGGING TIME, after the search or fetch had been run and its result read; it describes what was then expected given the preceding result and is NOT a pre-registered prior. Only the first-search priors for KR, SG, PT, EU, FR, ES, NL, SE, AU and the Korean Co-1 query were written before any search ran (priors.txt, written 02:36:01 UTC; first WebSearch about 02:36:03 UTC). All search rows of this batch were logged after the fact, in one pass.', 0, 'Expect CERMI Comunidad de Madrid to describe itself as a platform of disability organisations; asks whether it is DPO-led (D-0178).', 'planned', NULL, NULL, '2026-10-01 03:42', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (171, 'accessible-circulation-geometry', 'ES', 'ES', NULL, 'co1', NULL, 'https://www.madrid.es/UnidadesDescentralizadas/Discapacidad/publicaciones/MetodologiaAccesibilidadEspaciosPublicos/metodologiaaccesibilidadespaciospublicos.pdf', NULL, 'web', 'scoping', NULL, 1, 1, 1, 'partial', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:05', 'RE-RETRIEVED, 200, 2.0 MB, sha256 prefix 76d6a5953998c402 IDENTICAL to batch 21''s artefact. Authorship: title page and every footer ''CERMI Comunidad de Madrid''; last page ''Con el apoyo de'' the Ayuntamiento (supporter, not author -- candidate 132''s title ''Ayuntamiento de Madrid / CERMI'' over-attributed). p. 24: 10% for ramps <3 m, 8% for 3-10 m (an ECHO of Orden VIV/561/2010, derogated 2022-01-02). p. 10: slopes above 6% ''empiezan a tener problemas importantes'' and above 10% ''impracticable''. R7 HARM FINDING. Admitted T3 grey as REF-01029. || CORRECTED 2026-10-01: target_evidence_type grey -> co1: this follow-up retrieved a candidate surfaced by a Co-1-channel search (disability-sector organisation output); ''grey'' was the tier it was later ADMITTED at (T3), not what it was aimed at, and labelling a Swedish/Spanish search ''grey'' reads as the language-based down-tiering R5 forbids. The admitted tier stays T3 grey: Co-1 provenance is not evidenced in the bytes (D-0178). || CORRECTED 2026-10-01: target_evidence_type ''grey'' -> ''co1'' (misclassification corrected; the replaced value is kept here because the column no longer holds it) || CORRECTED 2026-10-01: PRIOR DISCLOSURE (adversarial pass F4): this row''s prior_expectation was COMPOSED AT LOGGING TIME, after the search or fetch had been run and its result read; it describes what was then expected given the preceding result and is NOT a pre-registered prior. Only the first-search priors for KR, SG, PT, EU, FR, ES, NL, SE, AU and the Korean Co-1 query were written before any search ran (priors.txt, written 02:36:01 UTC; first WebSearch about 02:36:03 UTC). All search rows of this batch were logged after the fact, in one pass. || CORRECTED 2026-10-01: R5 RETARGET DISCLOSURE (adversarial pass F9): the grey -> co1 change above was made AFTER research_batch_dod R5 reported these execs. R5''s rationale concerns non-English PEER-REVIEWED work, and neither document is peer-reviewed, so the R5 failure was arguably a false positive and a reasoned waiver was the honest route; the edit was nonetheless gate-driven. The earlier Co-1-channel exec for each document had already recorded it as Co-1-ADJACENT (FUB) or as a Co-1 DPO-sector question (CERMI) before this fetch was logged.', 1, 'R10 re-retrieval of candidate 132 (batch 21): expect byte-identical to the batch-21 retrieval and to carry p. 24 ramp tiers and a statement of authorship.', 'planned', NULL, NULL, '2026-10-01 03:42', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (172, 'accessible-circulation-geometry', 'AU', 'EN', NULL, 'code', NULL, 'Livable Housing Design Standard NCC 2022 H8 ramp gradient maximum 1:14 step-free path of travel ABCB', NULL, 'web', 'scoping', NULL, 9, 9, 0, 'none', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:05', 'Tool summary: step-free path gradient <=1:14 (or 1:20 over runs up to 15 m), 1200 mm landings. NOT USED as a value. Retrieved the ABCB NCC 2022 Vol. 2 Part H8 page: H8D2 refers to ''Clause 1.1 of the ABCB Standard for Livable Housing Design'' for the gradient and uses 1:14 only as an exemption trigger for average ground slope; the ramp-gradient clause lives in the separate ABCB Standard document, NOT retrieved. NCC 2025 currency unchecked.', 0, 'Livable Housing Design Standard / NCC 2022 Volume 2 H8 gives a ramp gradient near 1:14 for dwelling access; AS 1428.1 itself is paywalled; expect ABCB free text for the NCC.', 'planned', NULL, NULL, '2026-10-01 03:05', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (173, 'accessible-circulation-geometry', 'ES', 'ES', NULL, 'code', NULL, 'https://www.boe.es/diario_boe/txt.php?id=BOE-A-2010-4057', NULL, 'web', 'scoping', NULL, 1, 1, 0, 'saturated', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:06', 'RETRIEVED, 200, 133 kB. Art. 14.1 b): 10% for runs up to 3 m, 8% up to 10 m -- the figures CERMI Madrid (REF-01029) reproduces. BUT the BOE analysis block reads ''Fecha de derogación: 02/01/2022 ... SE DEROGA, por Orden TMA/851/2021'' (BOE-A-2021-13488): NOT IN FORCE. Screened out as superseded; the in-force successor is REF-01028. Staged as OUT-OF-SCOPE so it is not re-admitted from a vendor or council page that still cites it. || CORRECTED 2026-10-01: Linked a derived visible-text extraction (ce7c5fdc63f3bb2c-text.txt) alongside the persisted original, so a candidate row can quote it (the PDF/HTML itself is not quote-decodable for add-candidate''s checker). || CORRECTED 2026-10-01: result artefact(s) added: retrieval-log/session_2026-10-01-research-batch-23/ce7c5fdc63f3bb2c-text.txt || CORRECTED 2026-10-01: PRIOR DISCLOSURE (adversarial pass F4): this row''s prior_expectation was COMPOSED AT LOGGING TIME, after the search or fetch had been run and its result read; it describes what was then expected given the preceding result and is NOT a pre-registered prior. Only the first-search priors for KR, SG, PT, EU, FR, ES, NL, SE, AU and the Korean Co-1 query were written before any search ran (priors.txt, written 02:36:01 UTC; first WebSearch about 02:36:03 UTC). All search rows of this batch were logged after the fact, in one pass.', 0, 'Follow-up on the CERMI-cited root: expect Orden VIV/561/2010 art. 14 to give 10% to 3 m and 8% to 10 m and to be in force.', 'planned', NULL, NULL, '2026-10-01 03:42', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (174, 'accessible-circulation-geometry', 'AU', 'EN', NULL, 'code', NULL, 'https://abcb.gov.au/editions/ncc-2022/adopted/volume-two/h-class-1-and-10-buildings/part-h8-livable-housing-design', NULL, 'web', 'scoping', NULL, 1, 1, 0, 'partial', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:06', 'RETRIEVED, 200, 117 kB. H8D2: a Class 1a dwelling must comply with the ABCB Standard for Livable Housing Design; 1:14 appears only as an EXEMPTION TRIGGER (average ground slope exceeding 1:14), and the ramp gradient and length limits are in ''Clause 1.1(4)'' of the separate Standard, not on this page. Not admitted. NCC 2022 is the edition on this page; NCC 2025 currency unchecked. || CORRECTED 2026-10-01: Linked a derived visible-text extraction (f9b1b4f92ea0ebc2-text.txt) alongside the persisted original, so a candidate row can quote it (the PDF/HTML itself is not quote-decodable for add-candidate''s checker). || CORRECTED 2026-10-01: result artefact(s) added: retrieval-log/session_2026-10-01-research-batch-23/f9b1b4f92ea0ebc2-text.txt || CORRECTED 2026-10-01: PRIOR DISCLOSURE (adversarial pass F4): this row''s prior_expectation was COMPOSED AT LOGGING TIME, after the search or fetch had been run and its result read; it describes what was then expected given the preceding result and is NOT a pre-registered prior. Only the first-search priors for KR, SG, PT, EU, FR, ES, NL, SE, AU and the Korean Co-1 query were written before any search ran (priors.txt, written 02:36:01 UTC; first WebSearch about 02:36:03 UTC). All search rows of this batch were logged after the fact, in one pass.', 0, 'Follow-up: expect NCC 2022 Vol. 2 H8 to state the step-free path ramp gradient.', 'planned', NULL, NULL, '2026-10-01 03:42', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session") VALUES (175, 'accessible-circulation-geometry', 'SE', 'SV', NULL, 'national_fw', NULL, 'https://www.boverket.se/sv/PBL-kunskapsbanken/regler-om-byggande/tomter/gangvagar/', NULL, 'web', 'scoping', NULL, 1, 1, 0, 'partial', NULL, NULL, 0, 'session_2026-10-01-research-batch-23', '2026-10-01 03:10', 'RETRIEVED, 200, 861 kB HTML. Restates BFS 2024:13 2 kap. 3 § (gångvägar luta högst 1:12) and says the regulations set no slope at which a walkway must become a ramp: "Reglerna anger inte någon viss lutning som gräns för när vägen ska vara utförd som en ramp." A real GAP-033 datum: Sweden does not separate ramp from sloped walkway at this point. || CORRECTED 2026-10-01: Linked a derived visible-text extraction so the candidate row can quote it. || CORRECTED 2026-10-01: result artefact(s) added: retrieval-log/session_2026-10-01-research-batch-23/c8e6468abcd38ec3-text.txt || CORRECTED 2026-10-01: PRIOR DISCLOSURE (adversarial pass F4): this row''s prior_expectation was COMPOSED AT LOGGING TIME, after the search or fetch had been run and its result read; it describes what was then expected given the preceding result and is NOT a pre-registered prior. Only the first-search priors for KR, SG, PT, EU, FR, ES, NL, SE, AU and the Korean Co-1 query were written before any search ran (priors.txt, written 02:36:01 UTC; first WebSearch about 02:36:03 UTC). All search rows of this batch were logged after the fact, in one pass.', 0, 'Follow-up on a Boverket guidance page surfaced by the Funktionsratt search: expect it to restate the plot walkway rule and say how a ramp is distinguished from a sloped walkway.', 'planned', NULL, NULL, '2026-10-01 03:42', 'session_2026-10-01-research-batch-23');
