INSERT INTO "search_admissions" ("exec_id", "ref_id", "created_at", "created_by_session") VALUES (189, 'REF-01032', '2026-10-01 03:41', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id", "surfaced_in", "surfaced_quote", "updated_at", "updated_by_session") VALUES (136, 160, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Boverkets föreskrifter om krav på tomter m.m. (BFS 2024:13) — 2 kap. 3 § gångvägar luta högst 1:12', 'https://rinfo.boverket.se/BFS2024-13/pdf/BFS2024-13.pdf', 'RESOLVED', 6, 0, 'NOT ADMITTED: a WALKWAY-on-plot rule (gångvägar mellan entréer och målpunkter), not a ramp rule; whether route slope belongs under parameter 3 is GAP-033''s open scope question. The Boverket page on walkways says the 1:12 applies "oavsett om lutningen är en del av exempelvis en hårdgjord markyta eller om den är utförd som en ramp" -- i.e. Sweden does not distinguish ramp from sloped walkway at this point.', 'HYPOTHESIS (R15): admit as a SE T6 code source with one extraction if GAP-033 resolves route gradient into parameter 3. Retrieved 200, 5 pp., printed 20 Nov 2024, in force 1 July 2025 (2 kap. 3 §: "Gångvägar som avses i 2 § ska ... 3. luta högst 1:12"). Same 1:12 as the building rule admitted as REF-01023.', 'session_2026-10-01-research-batch-23', '2026-10-01 03:07', NULL, 'retrieval-log/session_2026-10-01-research-batch-23/24b5e81b0f4a0928-text.txt', 'luta högst 1:12', '2026-10-01 03:07', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id", "surfaced_in", "surfaced_quote", "updated_at", "updated_by_session") VALUES (137, 173, 'accessible-circulation-geometry', NULL, 'OUT-OF-SCOPE', 'Orden VIV/561/2010, de 1 de febrero — documento técnico de condiciones básicas de accesibilidad en espacios públicos urbanizados (art. 14 Rampas)', 'https://www.boe.es/diario_boe/txt.php?id=BOE-A-2010-4057', 'RESOLVED', 6, 0, 'NOT ADMITTED: DEROGATED on 2 January 2022 by Orden TMA/851/2021 (BOE analysis block: "Fecha de derogación: 02/01/2022", "SE DEROGA, por Orden TMA/851/2021"). The in-force successor is admitted as REF-01028. Recorded so the repealed order is not re-admitted from a council or vendor page that still cites it.', 'Art. 14.1 b) read 10% to 3 m and 8% to 10 m (the successor keeps the percentages and caps the run at 9 m). It is the root of the figures REF-01029 (CERMI Madrid, Dec 2018) restates.', 'session_2026-10-01-research-batch-23', '2026-10-01 03:07', NULL, 'retrieval-log/session_2026-10-01-research-batch-23/ce7c5fdc63f3bb2c-text.txt', 'La pendiente longitudinal máxima será del 10% para tramos de hasta 3 m de longitud y del 8% para tramos de hasta 10 m de longitud.', '2026-10-01 03:07', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id", "surfaced_in", "surfaced_quote", "updated_at", "updated_by_session") VALUES (138, 174, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'ABCB Standard for Livable Housing Design (2022), Clause 1.1 — step-free access path: gradient and length limits', 'https://abcb.gov.au/editions/ncc-2022/adopted/volume-two/h-class-1-and-10-buildings/part-h8-livable-housing-design', 'RESOLVED', 6, 0, 'NOT ADMITTED: the NCC 2022 Vol. 2 H8 page retrieved defers the gradient and length limits to Clause 1.1(4) of the separate ABCB Standard, which was not located or retrieved this batch; the page itself uses 1:14 only as an exemption trigger (average ground slope). A web-search summary said the Standard sets 1:14 (1:20 over runs up to 15 m) -- unverified, not used.', 'HYPOTHESIS (R15): the Standard (Livable Housing Design, ABCB 2022) is the AU primary for private dwellings that AS 1428.1 does not cover (lead 88). NCC 2025 currency unchecked. Next: locate the Standard PDF on abcb.gov.au and read Clause 1.1.', 'session_2026-10-01-research-batch-23', '2026-10-01 03:07', NULL, 'retrieval-log/session_2026-10-01-research-batch-23/f9b1b4f92ea0ebc2-text.txt', 'Even if Clause 1.1 is not complied with, all other relevant provisions of the ABCB Standard for Livable Housing Design must still be complied with.', '2026-10-01 03:07', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id", "surfaced_in", "surfaced_quote", "updated_at", "updated_by_session") VALUES (139, 155, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Gatu- och fastighetskontoret (Stockholm), tjänsteutlåtande 2001-08-02: Förbättrad tillgänglighet till offentliga platser med hjälp av ramper', 'https://insynsverige.se/documentHandler.ashx?did=52240', 'RESOLVED', 3, 0, 'NOT ADMITTED: a 2001 municipal officer memo, found by a mismatched search hit (the query sought a 2007-era DPO consultation reply). It states the Stockholm office''s own requirement as 1:20 "för att personer på egen hand ska kunna ta sig upp" while noting that a 1:20 ramp for a single step is 3 m long and unwieldy in old streets -- a stated trade-off between independence and space.', 'HYPOTHESIS (R15): a Swedish municipal source (sub-national, Bucket-1 country) with the same 1:20 independence warrant as FUB 2007 and the ALM 2 advice. Date, authorship and whether the 1:20 is a binding municipal rule are not established from the 4-page memo; read the attached letter from the handikapprådet chair before any admission.', 'session_2026-10-01-research-batch-23', '2026-10-01 03:07', NULL, 'retrieval-log/session_2026-10-01-research-batch-23/6ce224bbadd7b205-text.txt', 'våra krav på ramplutningar är 1:20, för att personer på egen hand ska kunna ta sig upp', '2026-10-01 03:07', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id", "surfaced_in", "surfaced_quote", "updated_at", "updated_by_session") VALUES (140, 143, 'accessible-circulation-geometry', NULL, 'OUT-OF-SCOPE', 'CEN/CLC JTC 11 — Towards common European criteria on accessibility of the built environment: Outcomes of Mandate M/420 (workshop deck, 22 March 2021)', 'https://www.une.org/normalizacion_documentos/PT%20EN%2017210.pdf', 'RESOLVED', 4, 0, 'NOT ADMITTED: 18 slides listing the structure of EN 17210:2021 (chapter 10 "Vertical circulation (ramps, stairs, handrails, lifts, escalators)"); it states no ramp gradient. Its only use is to contradict a web-search summary that placed a ramp clause in chapter 7.', 'EN 17210:2021 itself is paywalled (research_code_leads). The Dutch Bbl nota (REF-01020) says the small-rise ramp tiers come from NEN 9120, the Dutch elaboration of EN 17210.', 'session_2026-10-01-research-batch-23', '2026-10-01 03:07', NULL, 'retrieval-log/session_2026-10-01-research-batch-23/a426a8c5ff9b197e-text.txt', 'Vertical circulation (ramps, stairs, handrails, lifts, escalators)', '2026-10-01 03:07', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id", "surfaced_in", "surfaced_quote", "updated_at", "updated_by_session") VALUES (141, 175, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Boverket PBL-kunskapsbanken: Tillgängliga, användbara och säkra gångvägar (guidance on BFS 2024:13)', 'https://www.boverket.se/sv/PBL-kunskapsbanken/regler-om-byggande/tomter/gangvagar/', 'RESOLVED', 5, 0, 'NOT ADMITTED: guidance restating a rule already staged as candidate 136 (BFS 2024:13); admit the two together only if GAP-033 resolves route slope into parameter 3.', 'HYPOTHESIS (R15): a T5 national_fw guidance page. Its distinctive content is the statement that no slope marks the ramp/walkway boundary, plus "Lutningen ... får vara som brantast 1:12, vilket är ungefär 8 procent."', 'session_2026-10-01-research-batch-23', '2026-10-01 03:10', NULL, 'retrieval-log/session_2026-10-01-research-batch-23/c8e6468abcd38ec3-text.txt', 'Reglerna anger inte någon viss lutning som gräns för när vägen ska vara utförd som en ramp.', '2026-10-01 03:10', 'session_2026-10-01-research-batch-23');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id", "surfaced_in", "surfaced_quote", "updated_at", "updated_by_session") VALUES (142, 176, 'accessible-circulation-geometry', NULL, 'OUT-OF-SCOPE', 'Boverket PBL-kunskapsbanken: Säkra trappor och ramper (guidance; restates BFS 2024:12 2 kap. 4 §)', 'https://www.boverket.se/sv/PBL-kunskapsbanken/regler-om-byggande/sakerhet-anvandning/trappor-ramper/', 'RESOLVED', 5, 0, 'NOT ADMITTED: duplicates the regulation already admitted as REF-01023; the page adds only safety-of-use provisions (guards, run-off protection) that belong to other parameters.', 'Recorded so a later pass does not re-screen it.', 'session_2026-10-01-research-batch-23', '2026-10-01 03:10', NULL, 'retrieval-log/session_2026-10-01-research-batch-23/430b235b306662fb-text.txt', 'En ramp, som är till för att uppfylla kraven enligt 1 § och 2 § andra stycket, ska luta högst 1:12.', '2026-10-01 03:10', 'session_2026-10-01-research-batch-23');
