INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (82, 'REF-01019', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'KR', NULL, 'numerical', '1:12', 'rise:run ratio (maximum; the rule writes 12분의 1)', '경사로의 기울기는 12분의 1 이하로 하여야 한다.', '별표 1 제12호 나목(1)', NULL, 'committee_assertion', 'REF-01031', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, 'section', NULL, NULL, '별표 1 제12호', '나', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'MANDATORY, NOT ADVISORY: the page''s own 비고 states that items phrased ''…할 수 있다'' are recommendations (권장사항); this item is phrased ''하여야 한다'' (shall). A DISTINCT ELEMENT NOT EXTRACTED HERE: item 1 나목(1) sets the gradient of an 접근로 (approach path) at 18분의 1 or less, relaxed to 12분의 1 where terrain makes that difficult -- an approach path, not a 경사로 (ramp); route-vs-ramp scope is GAP-033''s open question. SOURCE QUALITY: retrieved from a non-governmental legal wiki (NEPLA) reproducing the rule text under the amendment stamp <개정 2023. 12. 11.>; the official host (law.go.kr) was unreachable from this environment (TLS connection reset, curl exit 35), hence verification UNVERIFIED and metadata GREY. The issuing ministry is not stated in the retrieved page, and currency after the 2023-12-11 stamp is unconfirmed. || 2026-10-01 root_ref_id SET REF-01019 -> REF-01031 (ADVERSARIAL-PASS REPAIR (F3/F11). Re-rooted to the OFFICIAL text, REF-01031 (law.go.kr flDownload PDF retrieved after the pass; item 12 reads identically to this mirror). CORRECTION of this row''s note: it said the official host was unreachable; the law.go.kr page resets the connection but the flDownload endpoint serves the Annex. REF-01019 stays as the record of the mirror first retrieved.)', '2026-10-01 02:58', 'session_2026-10-01-research-batch-23', '2026-10-01 03:39', 'session_2026-10-01-research-batch-23', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (83, 'REF-01019', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'KR', NULL, 'numerical', '1:8', 'rise:run ratio (conditional relaxation ceiling; all three conditions required)', '다음의 요건을 모두 충족하는 경우에는 경사로의 기울기를 8분의 1까지 완화할 수 있다. (가) 신축이 아닌 기존시설에 설치되는 경사로일 것 (나) 높이가 1미터 이하인 경사로로서 시설의 구조 등의 이유로 기울기를 12분의 1이하로 설치하기가 어려울 것 (다) 시설관리자 등으로부터 상시보조서비스가 제공될 것', '별표 1 제12호 나목(2)', NULL, 'committee_assertion', 'REF-01031', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, 'section', NULL, NULL, '별표 1 제12호', '나', '2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'THE ONLY RELAXATION IN THE RULE IS CONDITIONED ON HUMAN ASSISTANCE. All of: (가) an existing, not new, facility; (나) ramp height 1 m or less and 1/12 structurally difficult; (다) continuous assistance service provided by the facility manager (상시보조서비스). No other source in this corpus makes a steeper ramp conditional on a staffing provision. The verb is 완화할 수 있다 (may be relaxed): a permission, read as a permission and not as a 비고 recommendation. || 2026-10-01 root_ref_id SET REF-01019 -> REF-01031 (ADVERSARIAL-PASS REPAIR (F11). Re-rooted to the official text, REF-01031. CORRECTION: the note above read the verb 완화할 수 있다 as ''a permission and not a 비고 recommendation''. The Annex''s own 비고 (official PDF p. 22) says items phrased ''…할 수 있다'' are 권장사항 (recommendations) and this clause is so phrased; whether the 비고 was written to cover a relaxation permission is not stated. That reading is WITHDRAWN as an override of the source''s own convention; the verb''s status is left open (see REF-01031''s relaxation row).)', '2026-10-01 02:58', 'session_2026-10-01-research-batch-23', '2026-10-01 03:39', 'session_2026-10-01-research-batch-23', 'condition', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (84, 'REF-01020', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'NL', NULL, 'numerical', '1:6', 'rise:run ratio (maximum) where the height difference is <= 0.05 m', '1 : 6 als het hoogteverschil niet groter is dan 0,05 m', 'Stb. 2024, 368, art. I onderdeel R, art. 4.30 lid 2 onder a (nieuw)', NULL, 'committee_assertion', 'REF-01020', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, 'section', NULL, NULL, 'Stb. 2024, 368 art. I onderdeel R', 'art. 4.30 lid 2', 'a', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'STEEPEST RAMP TIER IN ANY SOURCE OF THIS CORPUS, for a threshold-scale rise. TIER ADDED BY THE 2024 AMENDING DECREE; in force 1 July 2025 (Artikel II lid 2 lists onderdeel R). The operative text is an AMENDMENT, so the lead-in of art. 4.30 lid 2 is not reproduced in it: the comparator ''<='' is read from the tiers'' function and from IPLO''s statement of the article (''De hellingbaan mag niet te steil zijn (artikel 4.30 Bbl)'', REF-01021).', '2026-10-01 02:58', 'session_2026-10-01-research-batch-23', '2026-10-01 02:58', 'session_2026-10-01-research-batch-23', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (85, 'REF-01020', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'NL', NULL, 'numerical', '1:10', 'rise:run ratio (maximum) where the height difference is > 0.05 m and <= 0.10 m', '1 : 10 als het hoogteverschil groter is dan 0,05 m, maar niet groter dan 0,10 m', 'Stb. 2024, 368, art. I onderdeel R, art. 4.30 lid 2 onder b (nieuw)', NULL, 'committee_assertion', 'REF-01020', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, 'section', NULL, NULL, 'Stb. 2024, 368 art. I onderdeel R', 'art. 4.30 lid 2', 'b', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'RISE-CONDITIONED TIER. TIER ADDED BY THE 2024 AMENDING DECREE; in force 1 July 2025 (Artikel II lid 2 lists onderdeel R). The operative text is an AMENDMENT, so the lead-in of art. 4.30 lid 2 is not reproduced in it: the comparator ''<='' is read from the tiers'' function and from IPLO''s statement of the article (''De hellingbaan mag niet te steil zijn (artikel 4.30 Bbl)'', REF-01021).', '2026-10-01 02:58', 'session_2026-10-01-research-batch-23', '2026-10-01 02:58', 'session_2026-10-01-research-batch-23', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (86, 'REF-01020', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'NL', NULL, 'numerical', '1:12', 'rise:run ratio (maximum) where the height difference is > 0.10 m and <= 0.25 m', '1 : 12 als het hoogteverschil groter is dan 0,10 m, maar niet groter dan 0,25 m', 'Stb. 2024, 368, art. I onderdeel R, art. 4.30 lid 2 onder c (nieuw)', NULL, 'committee_assertion', 'REF-01020', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, 'section', NULL, NULL, 'Stb. 2024, 368 art. I onderdeel R', 'art. 4.30 lid 2', 'c', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'REWORDED FROM THE FORMER FIRST TIER (''Onderdeel c (nieuw) komt te luiden''; the former a-c are re-lettered c-e). The 1:16 and 1:20 tiers for larger rises are unchanged text and are NOT in this decree''s pages; they are stated in REF-01021 (IPLO). TIER ADDED BY THE 2024 AMENDING DECREE; in force 1 July 2025 (Artikel II lid 2 lists onderdeel R). The operative text is an AMENDMENT, so the lead-in of art. 4.30 lid 2 is not reproduced in it: the comparator ''<='' is read from the tiers'' function and from IPLO''s statement of the article (''De hellingbaan mag niet te steil zijn (artikel 4.30 Bbl)'', REF-01021).', '2026-10-01 02:58', 'session_2026-10-01-research-batch-23', '2026-10-01 02:58', 'session_2026-10-01-research-batch-23', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (87, 'REF-01021', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'NL', NULL, 'numerical', '1:16', 'rise:run ratio (maximum) where the height difference is > 0.25 m and <= 0.50 m', '> 25 cm en ≤ 50 cm 1 : 16 Bij een hoogteverschil van 40 cm, moet de lengte minstens 640 cm zijn', 'IPLO, Helling, Tabel: steilte hellingbaan (art. 4.30 Bbl)', NULL, 'untraced', 'REF-01021', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, 'section', NULL, NULL, 'Tabel: steilte hellingbaan', NULL, 'rij 4', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'RISE-CONDITIONED TIER. Government guidance page (Informatiepunt Leefomgeving) restating Bbl art. 4.30. NOT an independent source for the 1:6, 1:10 and 1:12 rows, which are the Staatsblad''s (REF-01020) and are not re-extracted here (point, do not copy). The 1:16 and 1:20 rows rest on IPLO''s restatement alone: the legal text of those two rows was not retrieved (wetten.overheid.nl closed the connection, HTTP/2 PROTOCOL_ERROR then empty reply; inview.nl returned 403). The same page states maximum ramp height 1 m and minimum width 1.1 m (other parameters). || 2026-10-01 root_type SET committee_assertion -> untraced (ADVERSARIAL-PASS REPAIR (F13). IPLO restates Bbl art. 4.30''s 1:16 tier; the legal text of that row was not retrieved (wetten.overheid.nl, inview.nl failed), so the root is not held in this corpus: ''untraced''.)', '2026-10-01 02:59', 'session_2026-10-01-research-batch-23', '2026-10-01 03:39', 'session_2026-10-01-research-batch-23', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (88, 'REF-01021', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'NL', NULL, 'numerical', '1:20', 'rise:run ratio (maximum) where the height difference is > 0.50 m and <= 1.00 m', '> 50 cm en ≤ 100 cm 1 : 20 Bij een hoogteverschil van 60 cm, moet de lengte minstens 1200 cm zijn', 'IPLO, Helling, Tabel: steilte hellingbaan (art. 4.30 Bbl)', NULL, 'untraced', 'REF-01021', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, 'section', NULL, NULL, 'Tabel: steilte hellingbaan', NULL, 'rij 5', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'GENTLEST TIER; THE ONLY ONE THAT GOVERNS A RAMP OF NORMAL RISE (0.5-1.0 m). Government guidance page (Informatiepunt Leefomgeving) restating Bbl art. 4.30. NOT an independent source for the 1:6, 1:10 and 1:12 rows, which are the Staatsblad''s (REF-01020) and are not re-extracted here (point, do not copy). The 1:16 and 1:20 rows rest on IPLO''s restatement alone: the legal text of those two rows was not retrieved (wetten.overheid.nl closed the connection, HTTP/2 PROTOCOL_ERROR then empty reply; inview.nl returned 403). The same page states maximum ramp height 1 m and minimum width 1.1 m (other parameters). || 2026-10-01 root_type SET committee_assertion -> untraced (ADVERSARIAL-PASS REPAIR (F13). IPLO restates Bbl art. 4.30''s 1:20 tier; the legal text of that row was not retrieved, so the root is not held in this corpus: ''untraced''.)', '2026-10-01 02:59', 'session_2026-10-01-research-batch-23', '2026-10-01 03:39', 'session_2026-10-01-research-batch-23', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (90, 'REF-01023', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'SE', NULL, 'numerical', '1:12', 'rise:run ratio (maximum; a ramp provided to meet the accessibility requirements in a new building)', 'En ramp, som är till för att uppfylla kraven enligt 1 § och 2 § andra stycket, ska luta högst 1:12.', 'BFS 2024:12, 2 kap. 4 §', NULL, 'committee_assertion', 'REF-01023', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, 'section', NULL, NULL, '2 kap.', NULL, '4 §', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'BINDING FÖRESKRIFT (''ska''), in force 1 July 2025 (PDF p. 9, point 1); applies under ''2 kap. Utformningskrav vid uppförande av nya byggnader''. It replaces the accessibility provisions of the former BBR (BFS 2011:6); the transitional point 2 lets older BBR provisions be applied only as BFS 2024:14 point 3 allows. The same 1:12 ceiling is set for plot walkways in BFS 2024:13 2 kap. 3 § (retrieved, staged as a candidate and not extracted: route-vs-ramp scope, GAP-033). The public-places regulation (REF-01024) carries a GENERAL ADVICE of 1:20 -- Sweden holds two figures for two settings.', '2026-10-01 02:59', 'session_2026-10-01-research-batch-23', '2026-10-01 02:59', 'session_2026-10-01-research-batch-23', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (93, 'REF-01025', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'SE', NULL, 'qualitative', 'a 1:12 ramp gradient is a safety risk: it demands arm strength and great manoeuvring skill to keep the wheelchair from rolling backwards and tipping over', NULL, 'En ramplutning på 1:12 är en säkerhetsrisk. Det kräver kraft i armarna och stor manöverskicklighet för att inte rullstolen ska rulla bakåt och välta.', 'Yttrande, punkt 3:1222 (PDF pp. 2-3)', NULL, 'committee_assertion', 'REF-01025', NULL, 'stated_unmeasured', 'manual_self_propelled', 'Riksförbundet FUB is an organisation for people with intellectual disability (its name: För Utvecklingsstörda Barn, Ungdomar och Vuxna); no wheelchair-user authorship is evidenced in the retrieved bytes (D-0178), which is why the source is filed T3 grey rather than Co-1. The topic population (manual wheelchair users) is not the author organisation''s stated constituency.', NULL, 0, NULL, 'section', NULL, NULL, '3:1222', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'R7 HARM / INADEQUACY FINDING WITH A STATED MECHANISM (backward roll and tip-over; arm strength; manoeuvring skill) -- asserted, not measured; harm_finding=1. DATE AND TARGET: Stockholm 2007-01-10, a remissvar to Boverket''s proposal to revise BBR sections 3 and 8; the provision criticised was then BBR 3:1222. THE 1:12 CEILING WAS NOT CHANGED IN THE 17 YEARS TO BFS 2024:12 (REF-01023, in force 2025-07-01), which still reads ''ska luta högst 1:12''. Device inferred from the stated mechanism (arm strength): manual, self-propelled. || 2026-10-01 figure_role SET claim -> finding (Corrected same session before capture: a qualitative statement that asserts no value for the parameter is a ''finding'' (supplies direction), not a ''claim'' (value-supplying; assess_cell.gather_sources governs on claim/derived only). Mis-graded at write.)', '2026-10-01 02:59', 'session_2026-10-01-research-batch-23', '2026-10-01 03:01', 'session_2026-10-01-research-batch-23', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (94, 'REF-01025', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'SE', NULL, 'numerical', '1:20', 'rise:run ratio (requested maximum; a lifting device where it cannot be achieved)', 'Eftersom utgångspunkten för föreskrifterna är att en person självständigt ska kunna förflytta sig anser vi det absolut nödvändigt att lutningen 1:20 införs som standard. Vi yrkar att högsta tillåtna ramplutning anges till 1:20. Går inte detta att åstadkomma krävs lyftanordning.', 'Yttrande, punkt 3:1222 (PDF pp. 2-3)', NULL, 'committee_assertion', 'REF-01025', NULL, 'stated_unmeasured', 'manual_self_propelled', NULL, NULL, 0, NULL, 'section', NULL, NULL, '3:1222', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'A REQUESTED STANDARD (an advocacy demand), not a code value and not a measurement. Its stated warrant is independence of movement (''en person självständigt ska kunna förflytta sig''), the starting point the organisation reads into the regulation. The same 1:20 figure is the Swedish public-places general advice (REF-01024).', '2026-10-01 02:59', 'session_2026-10-01-research-batch-23', '2026-10-01 02:59', 'session_2026-10-01-research-batch-23', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (95, 'REF-01026', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'PT', NULL, 'numerical', '6%', '% longitudinal gradient (maximum) where the rise is <= 0.6 m and the horizontal projection <= 10 m; interpolated values permitted', '1) Ter uma inclinação não superior a 6%, vencer um desnível não superior a 0,6 m e ter uma projecção horizontal não superior a 10 m;', 'Anexo, 2.5.1 1)', NULL, 'committee_assertion', 'REF-01032', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, 'section', NULL, NULL, 'Anexo 2.5', '2.5.1', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'TIERED BY RISE AND RUN, with explicit permission to use interpolated values (''ou valores interpolados dos indicados''). Source quality: a transcription hosted by the Ordem dos Arquitectos whose first page says it ''não substitui a consulta da sua publicação em Diário da República''; diariodarepublica.pt returned only a JavaScript shell (no text), so the legal original was not retrieved -- GREY / UNVERIFIED. Portugal has no JurisdictionCode value (jurisdiction_db_vocabulary class, owner decision). Lead-in of 2.5.1: ''As rampas devem ter a menor inclinação possível'' -- the code states the least-possible-slope principle itself. || 2026-10-01 root_ref_id SET REF-01026 -> REF-01032 (ADVERSARIAL-PASS REPAIR (F7/F12). Re-rooted to the Diário da República ORIGINAL, REF-01032 (retrieved after the pass; text identical). CORRECTIONS: (1) the note called Portugal''s missing JurisdictionCode an ''owner decision''; the record shows it PENDING, not decided (sessions/session_2026-09-28-research-batch-22-selection.md section 3, ''Left to the owner''; references/project-standards.md 2026-09-28 ruling treats the class as blocked, not licensed). (2) Currency of Anexo 2.5 is NOT established: PGDL lists DL 136/2014, DL 125/2017, DL 95/2019 and DL 10/2024 as amending decrees; this row rests on the 2006 text.)', '2026-10-01 02:59', 'session_2026-10-01-research-batch-23', '2026-10-01 03:39', 'session_2026-10-01-research-batch-23', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (96, 'REF-01026', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'PT', NULL, 'numerical', '8%', '% longitudinal gradient (maximum) where the rise is <= 0.4 m and the horizontal projection <= 5 m; interpolated values permitted', '2) Ter uma inclinação não superior a 8%, vencer um desnível não superior a 0,4 m e ter uma projecção horizontal não superior a 5 m.', 'Anexo, 2.5.1 2)', NULL, 'committee_assertion', 'REF-01032', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, 'section', NULL, NULL, 'Anexo 2.5', '2.5.1', '2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'SECOND TIER OF THE NEW-BUILD RULE (steeper for shorter, lower ramps). Source quality: a transcription hosted by the Ordem dos Arquitectos whose first page says it ''não substitui a consulta da sua publicação em Diário da República''; diariodarepublica.pt returned only a JavaScript shell (no text), so the legal original was not retrieved -- GREY / UNVERIFIED. Portugal has no JurisdictionCode value (jurisdiction_db_vocabulary class, owner decision). Lead-in of 2.5.1: ''As rampas devem ter a menor inclinação possível'' -- the code states the least-possible-slope principle itself. || 2026-10-01 root_ref_id SET REF-01026 -> REF-01032 (ADVERSARIAL-PASS REPAIR (F7/F12). Re-rooted to the DR original REF-01032; same two corrections as extraction 95 (jurisdiction gap is pending not decided; Anexo 2.5 currency unestablished).)', '2026-10-01 02:59', 'session_2026-10-01-research-batch-23', '2026-10-01 03:39', 'session_2026-10-01-research-batch-23', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (97, 'REF-01026', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'PT', NULL, 'numerical', '12%', '% longitudinal gradient (maximum) in buildings under alteration or conservation only, where the rise is <= 0.1 m and the projection <= 0.83 m; a 10% step allows rise <= 0.2 m and projection <= 2 m', 'No caso de edifícios sujeitos a obras de alteração ou conservação, se as limitações de espaço impedirem a utilização de rampas com uma inclinação não superior a 8%, as rampas podem ter inclinações superiores se satisfizerem uma das seguintes situações ou valores interpolados dos indicados: 1) Ter uma inclinação não superior a 10%, vencer um desnível não superior a 0,2 m e ter uma projecção horizontal não superior a 2 m; 2) Ter uma inclinação não superior a 12%, vencer um desnível não superior a 0,1 m e ter uma projecção horizontal não superior a 0,83 m.', 'Anexo, 2.5.2', NULL, 'committee_assertion', 'REF-01032', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, 'section', NULL, NULL, 'Anexo 2.5', '2.5.2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'EXISTING-BUILDING CONCESSION, available only where space prevents 8%. Source quality: a transcription hosted by the Ordem dos Arquitectos whose first page says it ''não substitui a consulta da sua publicação em Diário da República''; diariodarepublica.pt returned only a JavaScript shell (no text), so the legal original was not retrieved -- GREY / UNVERIFIED. Portugal has no JurisdictionCode value (jurisdiction_db_vocabulary class, owner decision). Lead-in of 2.5.1: ''As rampas devem ter a menor inclinação possível'' -- the code states the least-possible-slope principle itself. || 2026-10-01 root_ref_id SET REF-01026 -> REF-01032 (ADVERSARIAL-PASS REPAIR (F7/F12). Re-rooted to the DR original REF-01032; same two corrections as extraction 95 (jurisdiction gap is pending not decided; Anexo 2.5 currency unestablished).)', '2026-10-01 02:59', 'session_2026-10-01-research-batch-23', '2026-10-01 03:39', 'session_2026-10-01-research-batch-23', 'condition', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (98, 'REF-01027', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'ES', NULL, 'numerical', '12%', '% longitudinal slope (general maximum for ramps)', 'Las rampas tendrán una pendiente del 12%, como máximo, excepto:', 'DB-SUA, SUA 1, 4.3.1 apartado 1', NULL, 'committee_assertion', 'REF-01027', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, 'section', NULL, NULL, 'SUA 1', '4.3.1', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'GENERAL RAMP RULE; ramps on accessible routes are the stricter exception (next row). The text is the Ministry''s consolidated articulado (as modified through RD 450/2022; correction of errors BOE 2/02/2023); the Ministry''s comments in the same PDF are ''orientativo e informativo ... no teniendo carácter reglamentario'' (p. 2) and are not extracted.', '2026-10-01 03:00', 'session_2026-10-01-research-batch-23', '2026-10-01 03:00', 'session_2026-10-01-research-batch-23', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (99, 'REF-01027', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'ES', NULL, 'numerical', '6%', '% longitudinal slope for ramps on accessible routes: <=10% where the run is < 3 m, <=8% where < 6 m, <=6% otherwise', 'las que pertenezcan a itinerarios accesibles, cuya pendiente será, como máximo, del 10% cuando su longitud sea menor que 3 m, del 8% cuando la longitud sea menor que 6 m y del 6% en el resto de los casos.', 'DB-SUA, SUA 1, 4.3.1 apartado 1 a)', NULL, 'committee_assertion', 'REF-01027', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, 'section', NULL, NULL, 'SUA 1', '4.3.1', '1', 'a', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'THE ACCESSIBLE-ROUTE TIERING (10/8/6 by run length). Run lengths are measured in horizontal projection, per section; on a curved ramp the slope is measured on the least favourable side. Section 4.3.2(1) caps accessible-route ramp sections at 9 m (a length parameter, not extracted). || 2026-10-01 comparator CONFIRMED <= (ADVERSARIAL-PASS CORRECTION (F15). The sentence ''Run lengths are measured in horizontal projection, per section'' is drawn from the Ministry''s non-regulatory COMMENTS, which this row says are not extracted; it is withdrawn from the row. Also: the articulado is the 14 junio 2022 text (RD 450/2022) and the 15 julio 2024 date is the comments version (PDF p. 1: ''Articulado: 14 junio 2022 / Comentarios: 15 julio 2024''), so the source''s pub_year 2024 is the comments edition.)', '2026-10-01 03:00', 'session_2026-10-01-research-batch-23', '2026-10-01 03:39', 'session_2026-10-01-research-batch-23', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (100, 'REF-01028', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'ES', NULL, 'numerical', '8%', '% longitudinal slope for ramps linked to an accessible pedestrian itinerary in urbanised public space: <=10% for runs up to 3.00 m, <=8% for runs up to 9.00 m (horizontal projection); run capped at 9.00 m', 'La pendiente longitudinal máxima será del 10% para tramos de hasta 3,00 m de longitud, y del 8% para tramos de hasta 9,00 m de longitud, medidos en proyección horizontal.', 'Orden TMA/851/2021, art. 14 apartado 2 c)', NULL, 'committee_assertion', 'REF-01028', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, 'section', NULL, NULL, 'art. 14', '2', 'c', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'IN FORCE FROM 2022-01-02 AND THE SUCCESSOR OF ORDEN VIV/561/2010, which BOE shows as derogated on 2022-01-02 (retrieved: BOE-A-2010-4057, ''Fecha de derogación: 02/01/2022'', ''SE DEROGA, por Orden TMA/851/2021''). The 2010 order''s art. 14.1 b) read 10% to 3 m and 8% to 10 m; the 2021 order keeps the percentages and shortens the run cap from 10 m to 9 m. A ramp is DEFINED here as a plane above 6% (art. 14.1) -- a classification threshold, not a limit. AN UNVERIFIED WEB-SEARCH SUMMARY this session said the order sets a 6% maximum; the retrieved BOE text does not. || 2026-10-01 comparator CONFIRMED <= (ADVERSARIAL-PASS CORRECTION (F5/F6). The note above said the retrieved BOE text does not set a 6% maximum. IT DOES: art. 5.2 g) of Orden TMA/851/2021 reads ''La pendiente longitudinal máxima será del 6%'' for the accessible pedestrian itinerary -- a ROUTE/street rule (GAP-033 scope), not the ramp rule of art. 14, and not extracted here. The web-search summary was route-scoped, not false. Also: the retrieved artefact is a BOE consolidation (''Última actualización publicada el 03/09/2026'', ''sin valor oficial'') that flags Real Decreto 707/2026 as altering arts. 32 and 47 from 2027-01-02; it carries no such flag at art. 14.)', '2026-10-01 03:00', 'session_2026-10-01-research-batch-23', '2026-10-01 03:39', 'session_2026-10-01-research-batch-23', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (101, 'REF-01029', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'ES', NULL, 'numerical', '8%', '% longitudinal slope: <=10% for ramps under 3 m, <=8% for ramps of 3-10 m', 'Rampas de menos de 3 m. pendiente máxima 10%. Rampas de entre 3 y 10 m. pendiente máxima 8%.', 'Metodología p. 24, Pendientes longitudinales máximas', NULL, 'untraced', 'REF-01029', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, 'section', NULL, NULL, 'p. 24', 'Pendientes longitudinales máximas', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'AN ECHO, NOT AN INDEPENDENT FIGURE: it reproduces the figures of Orden VIV/561/2010 art. 14.1 b) (retrieved from BOE this session, BOE-A-2010-4057), in force when the Metodología was written (December 2018) and DEROGATED on 2022-01-02 by Orden TMA/851/2021 (REF-01028). Spain''s current urban-space rule keeps 10%/8% but caps the 8% tier at 9 m. The same page states a 2% maximum cross-slope: a different axis, not extracted. || 2026-10-01 root_type SET committee_assertion -> untraced (ADVERSARIAL-PASS REPAIR (F13). The 10%/8% tiers trace to Orden VIV/561/2010 art. 14.1 b), which was retrieved but NOT admitted (derogated 2022-01-02): the root is not held in this corpus, so ''untraced'' (batch-19 precedent), not a self-rooted committee assertion. (v_value_independence ignores committee_assertion and untraced rows alike; this keeps the typed column consistent with the note.))', '2026-10-01 03:00', 'session_2026-10-01-research-batch-23', '2026-10-01 03:39', 'session_2026-10-01-research-batch-23', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (102, 'REF-01029', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'ES', NULL, 'qualitative', 'above 6% (the legal limit) a sloping street is already seriously difficult for many people to travel, and from 10% it is impracticable', NULL, 'pendientes superiores al 6% (límite que marca la ley) empiezan a tener problemas importantes para ser recorridas por muchas personas y a partir del 10% es impracticable.', 'Metodología p. 10, 3.2 Condiciones orográficas', NULL, 'committee_assertion', 'REF-01029', NULL, 'stated_unmeasured', 'not_device_scoped', 'CERMI Comunidad de Madrid authored the document (title page and every footer) and the municipality is credited on the last page only as ''Con el apoyo de''. The retrieved bytes do not state who within CERMI wrote it or that disabled people did (D-0178), so Co-1 is NOT claimed: filed T3 grey, Co-1-adjacent.', NULL, 0, NULL, 'section', NULL, NULL, 'p. 10', '3.2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'R7 HARM / INADEQUACY FINDING: a practical-use threshold stated by a disability-sector platform, asserted not measured; harm_finding=1. It concerns STREET slope (calles en pendiente), a route and not a ramp -- GAP-033''s scope question -- so it is filed as a finding beside the ramp row, not as a ramp value. ''Límite que marca la ley'' is read as the 6% definition threshold of Orden VIV/561/2010 art. 14.1 (an inference; the Metodología does not cite the article at this point). || 2026-10-01 figure_role SET claim -> finding (Corrected same session before capture: a qualitative statement that asserts no value for the parameter is a ''finding'' (supplies direction), not a ''claim'' (value-supplying; assess_cell.gather_sources governs on claim/derived only). Mis-graded at write.) || 2026-10-01 extraction_method CONFIRMED full-read (ADVERSARIAL-PASS CORRECTION (F5). The inference above, that ''límite que marca la ley'' is the 6% ramp-definition threshold of art. 14.1, is WITHDRAWN. Orden VIV/561/2010 art. 5.2 h) separately sets ''La pendiente longitudinal máxima será del 6%'' for the accessible pedestrian itinerary, which is the limit a reader of ''calles en pendiente'' would reach for. The row stays a street-slope finding.)', '2026-10-01 03:00', 'session_2026-10-01-research-batch-23', '2026-10-01 03:39', 'session_2026-10-01-research-batch-23', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (103, 'REF-01030', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'FR', NULL, 'numerical', '6%', '% (maximum slope of an inclined plane on an accessible route in existing ERP/IOP; tolerated exceptionally up to 10% over <= 2 m and 12% over <= 0.50 m)', 'Lorsqu''une dénivellation ne peut être évitée, un plan incliné de pente inférieure ou égale à 6 % est aménagé afin de la franchir. Les valeurs de pentes suivantes sont tolérées exceptionnellement : jusqu''à 10 % sur une longueur inférieure ou égale à 2 m ; jusqu''à 12 % sur une longueur inférieure ou égale à 0,50 m.', 'Guide, B-2 2° a) Profil en long, Pentes (Arrêté du 8 décembre 2014, art. 2), p. 12', NULL, 'committee_assertion', 'REF-01030', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, 'section', NULL, NULL, 'Arrêté du 8 décembre 2014, art. 2', '2° a) Pentes', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'REPRODUCES THE ARRÊTÉ''S TEXT (the guide prints it in a block headed ''Arrêté du 8 décembre 2014, Article 2''). EXISTING-BUILDING REGIME ONLY (ERP/IOP in an existing built frame; arrêté du 8 décembre 2014). The NEW-ERP regime (arrêté du 20 avril 2017) was NOT retrieved: Légifrance returns 403 and two prefecture copies closed the connection (HTTP/2 stream errors, empty reply); research_code_leads 86 and 92 stay REFERENCE-ONLY and no figure for new ERP is asserted here. The guide''s preface says a companion guide on new ERP was still to come. Year 2019 is read from the URL (''2019 07'') and the PDF creationDate (2019-05-29); no date appears in the pages retrieved.', '2026-10-01 03:00', 'session_2026-10-01-research-batch-23', '2026-10-01 03:00', 'session_2026-10-01-research-batch-23', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (104, 'REF-01030', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'FR', NULL, 'qualitative', 'from 6% over several metres, many manual wheelchair users lose their autonomy and must ask for help; many other people with reduced mobility suffer comparable difficulty', NULL, 'À partir de 6 % sur plusieurs mètres, un nombre important de personnes en fauteuil roulant manuel vont perdre leur autonomie et devoir demander de l''aide. De nombreuses autres personnes à mobilité réduite subiront une gêne comparable.', 'Guide p. 12, commentary beside the arrêté text', NULL, 'committee_assertion', 'REF-01030', NULL, 'stated_unmeasured', 'manual_self_propelled', NULL, NULL, 0, NULL, 'section', NULL, NULL, 'Guide p. 12', 'commentary', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'THE MINISTRY''S OWN STATEMENT OF WHERE AUTONOMY IS LOST, asserted not measured (no study is cited in the pages retrieved); harm_finding=1. It sits in the commentary margin, not in the arrêté text. The requirement itself is 6%, so the arrêté''s ceiling is the point at which this guide says manual wheelchair users begin to lose independence. EXISTING-BUILDING REGIME ONLY (ERP/IOP in an existing built frame; arrêté du 8 décembre 2014). The NEW-ERP regime (arrêté du 20 avril 2017) was NOT retrieved: Légifrance returns 403 and two prefecture copies closed the connection (HTTP/2 stream errors, empty reply); research_code_leads 86 and 92 stay REFERENCE-ONLY and no figure for new ERP is asserted here. The guide''s preface says a companion guide on new ERP was still to come. Year 2019 is read from the URL (''2019 07'') and the PDF creationDate (2019-05-29); no date appears in the pages retrieved. || 2026-10-01 figure_role SET claim -> finding (Corrected same session before capture: a qualitative statement that asserts no value for the parameter is a ''finding'' (supplies direction), not a ''claim'' (value-supplying; assess_cell.gather_sources governs on claim/derived only). Mis-graded at write.)', '2026-10-01 03:00', 'session_2026-10-01-research-batch-23', '2026-10-01 03:01', 'session_2026-10-01-research-batch-23', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (105, 'REF-01030', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'FR', NULL, 'numerical', '5%', '% (recommended, not required)', 'on préférera un plan incliné dont la pente est inférieure ou égale à 5 %', 'Guide p. 12, commentary (ressauts successifs)', NULL, 'committee_assertion', 'REF-01030', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, 'section', NULL, NULL, 'Guide p. 12', 'commentary', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'A MINISTRY COMMENTARY RECOMMENDATION (the guide''s ''R : Recommandé'' convention), made while advising against successive small steps (ressauts); it is not the arrêté''s requirement, which is 6%. EXISTING-BUILDING REGIME ONLY (ERP/IOP in an existing built frame; arrêté du 8 décembre 2014). The NEW-ERP regime (arrêté du 20 avril 2017) was NOT retrieved: Légifrance returns 403 and two prefecture copies closed the connection (HTTP/2 stream errors, empty reply); research_code_leads 86 and 92 stay REFERENCE-ONLY and no figure for new ERP is asserted here. The guide''s preface says a companion guide on new ERP was still to come. Year 2019 is read from the URL (''2019 07'') and the PDF creationDate (2019-05-29); no date appears in the pages retrieved.', '2026-10-01 03:00', 'session_2026-10-01-research-batch-23', '2026-10-01 03:00', 'session_2026-10-01-research-batch-23', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (106, 'REF-01020', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'NL', NULL, 'qualitative', 'the added small-rise tiers were taken from draft NEN 9120, the Dutch elaboration of NEN-EN 17210', NULL, 'De toegevoegde afmetingen van de helling zijn overgenomen uit de in ontwikkeling zijnde NEN 9120 «Nederlandse uitwerking van NEN-EN 17210 Prestatie eisen voor toegankelijkheid en bruikbaarheid van gebouwen».', 'Stb. 2024, 368, nota van toelichting, onderdeel R (PDF p. 35)', NULL, 'committee_assertion', 'REF-01020', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, 'section', NULL, NULL, 'Stb. 2024, 368 nota van toelichting', 'onderdeel R', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'LINEAGE OF THE SMALL-RISE VALUES (the 1:6 and 1:10 tiers): they do not originate with the Dutch legislator; the nota says they come from NEN 9120 (then in development), itself the Dutch elaboration of EN 17210 (European). NEN 9120:2025 and EN 17210:2021 are paywalled and were not retrieved (research_code_leads). A DISCREPANCY INSIDE THE SOURCE: the nota says ''tot 5 mm en tussen 5 en 10 mm'' where the operative text reads 0,05 m and 0,10 m (5 and 10 cm); the operative text governs and the nota''s ''mm'' is read as a slip -- flagged, not corrected.', '2026-10-01 03:01', 'session_2026-10-01-research-batch-23', '2026-10-01 03:01', 'session_2026-10-01-research-batch-23', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (107, 'REF-01031', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'KR', NULL, 'numerical', '1:12', 'rise:run ratio (maximum; the rule writes 12분의 1)', '경사로의 기울기는 12분의 1 이하로 하여야 한다.', '별표 1 제12호 나목(1) (PDF p. 10)', NULL, 'committee_assertion', 'REF-01031', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, 'section', NULL, NULL, '별표 1 제12호', '나', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'MANDATORY WORDING: ''하여야 한다'' (shall). A DISTINCT ELEMENT NOT EXTRACTED: item 1 나목(1) sets the gradient of an 접근로 (approach path) at 18분의 1 or less, relaxable to 12분의 1 where terrain makes that difficult -- an approach path, not a 경사로 (ramp); route-vs-ramp scope is GAP-033''s open question. OFFICIAL TEXT: the law.go.kr download (PDF author ''법제처 국가법령정보센터'', file created 2026-03-31, 22 pp.) under the stamp <개정 2023. 12. 11.>; it reads identically to the NEPLA mirror admitted as REF-01019 for item 12 and the 비고, which is why REF-01019''s rows are re-rooted here. The issuing ministry is not named in the Annex text itself.', '2026-10-01 03:38', 'session_2026-10-01-research-batch-23', '2026-10-01 03:38', 'session_2026-10-01-research-batch-23', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (108, 'REF-01031', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'KR', NULL, 'numerical', '1:8', 'rise:run ratio (conditional relaxation ceiling; all three conditions required)', '다음의 요건을 모두 충족하는 경우에는 경사로의 기울기를 8분의 1까지 완화할 수 있다. (가) 신축이 아닌 기존시설에 설치되는 경사로일 것 (나) 높이가 1미터 이하인 경사로로서 시설의 구조 등의 이유로 기울기를 12분의 1이하로 설치하기가 어려울 것 (다) 시설관리자 등으로부터 상시보조서비스가 제공될 것', '별표 1 제12호 나목(2) (PDF p. 10)', NULL, 'committee_assertion', 'REF-01031', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, 'section', NULL, NULL, '별표 1 제12호', '나', '2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'THE ONLY RELAXATION IN THE RULE IS CONDITIONED ON HUMAN ASSISTANCE. All of: (가) an existing, not new, facility; (나) ramp height 1 m or less and 1/12 structurally difficult; (다) continuous assistance service provided by the facility manager (상시보조서비스). No other source in this corpus makes a steeper ramp conditional on a staffing provision. STATUS OF THE VERB IS LEFT OPEN: the Annex''s own 비고 (PDF p. 22) says items phrased ''…할 수 있다'' are 권장사항 (recommendations), and this clause is phrased ''완화할 수 있다''; whether the 비고 was written to cover a relaxation permission is not stated in the text, so neither ''permission'' nor ''recommendation'' is asserted here. OFFICIAL TEXT: the law.go.kr download (PDF author ''법제처 국가법령정보센터'', file created 2026-03-31, 22 pp.) under the stamp <개정 2023. 12. 11.>; it reads identically to the NEPLA mirror admitted as REF-01019 for item 12 and the 비고, which is why REF-01019''s rows are re-rooted here. The issuing ministry is not named in the Annex text itself.', '2026-10-01 03:38', 'session_2026-10-01-research-batch-23', '2026-10-01 03:38', 'session_2026-10-01-research-batch-23', 'condition', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (109, 'REF-01032', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'PT', NULL, 'numerical', '6%', '% longitudinal gradient (maximum) where the rise is <= 0.6 m and the horizontal projection <= 10 m; interpolated values permitted', '1) Ter uma inclinação não superior a 6 %, vencer um desnível não superior a 0,6 m e ter uma projecção horizontal não superior a 10 m;', 'Anexo, 2.5.1 1)', NULL, 'committee_assertion', 'REF-01032', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, 'section', NULL, NULL, 'Anexo 2.5', '2.5.1', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'TIERED BY RISE AND RUN, with explicit permission to use interpolated values (''ou valores interpolados dos indicados''). OFFICIAL ORIGINAL: Diário da República, 1.ª série, N.º 152, 8 de Agosto de 2006, DR p. 5678 (PDF p. 9 of 20); the text reads identically to the Ordem dos Arquitectos transcription admitted as REF-01026, whose rows are re-rooted here. CURRENCY NOT ESTABLISHED: the decree has been amended by DL 136/2014 (9 Sept), DL 125/2017 (4 Oct), DL 95/2019 (18 July) and DL 10/2024 (8 Jan) per the PGDL consolidation page retrieved this session (five versions listed); that page''s Anexo node did not load, so whether any amendment altered Anexo 2.5 is UNVERIFIED. Portugal has no JurisdictionCode value (jurisdiction_db_vocabulary class, left to the owner and not yet decided). Lead-in of 2.5.1: ''As rampas devem ter a menor inclinação possível''.', '2026-10-01 03:38', 'session_2026-10-01-research-batch-23', '2026-10-01 03:38', 'session_2026-10-01-research-batch-23', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (110, 'REF-01032', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'PT', NULL, 'numerical', '8%', '% longitudinal gradient (maximum) where the rise is <= 0.4 m and the horizontal projection <= 5 m; interpolated values permitted', '2) Ter uma inclinação não superior a 8 %, vencer um desnível não superior a 0,4 m e ter uma projecção horizontal não superior a 5 m.', 'Anexo, 2.5.1 2)', NULL, 'committee_assertion', 'REF-01032', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, 'section', NULL, NULL, 'Anexo 2.5', '2.5.1', '2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'SECOND TIER OF THE NEW-BUILD RULE (steeper for shorter, lower ramps). OFFICIAL ORIGINAL: Diário da República, 1.ª série, N.º 152, 8 de Agosto de 2006, DR p. 5678 (PDF p. 9 of 20); the text reads identically to the Ordem dos Arquitectos transcription admitted as REF-01026, whose rows are re-rooted here. CURRENCY NOT ESTABLISHED: the decree has been amended by DL 136/2014 (9 Sept), DL 125/2017 (4 Oct), DL 95/2019 (18 July) and DL 10/2024 (8 Jan) per the PGDL consolidation page retrieved this session (five versions listed); that page''s Anexo node did not load, so whether any amendment altered Anexo 2.5 is UNVERIFIED. Portugal has no JurisdictionCode value (jurisdiction_db_vocabulary class, left to the owner and not yet decided). Lead-in of 2.5.1: ''As rampas devem ter a menor inclinação possível''.', '2026-10-01 03:38', 'session_2026-10-01-research-batch-23', '2026-10-01 03:38', 'session_2026-10-01-research-batch-23', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (111, 'REF-01032', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'PT', NULL, 'numerical', '12%', '% longitudinal gradient (maximum) in buildings under alteration or conservation only, where the rise is <= 0.1 m and the projection <= 0.83 m; a 10% step allows rise <= 0.2 m and projection <= 2 m', 'No caso de edifícios sujeitos a obras de alteração ou conservação, se as limitações de espaço impedirem a utilização de rampas com uma inclinação não superior a 8%, as rampas podem ter inclinações superiores se satisfizerem uma das seguintes situações ou valores interpolados dos indicados: 1) Ter uma inclinação não superior a 10%, vencer um desnível não superior a 0,2 m e ter uma projecção horizontal não superior a 2 m; 2) Ter uma inclinação não superior a 12%, vencer um desnível não superior a 0,1 m e ter uma projecção horizontal não superior a 0,83 m.', 'Anexo, 2.5.2', NULL, 'committee_assertion', 'REF-01032', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, 'section', NULL, NULL, 'Anexo 2.5', '2.5.2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'EXISTING-BUILDING CONCESSION, available only where space prevents 8%. OFFICIAL ORIGINAL: Diário da República, 1.ª série, N.º 152, 8 de Agosto de 2006, DR p. 5678 (PDF p. 9 of 20); the text reads identically to the Ordem dos Arquitectos transcription admitted as REF-01026, whose rows are re-rooted here. CURRENCY NOT ESTABLISHED: the decree has been amended by DL 136/2014 (9 Sept), DL 125/2017 (4 Oct), DL 95/2019 (18 July) and DL 10/2024 (8 Jan) per the PGDL consolidation page retrieved this session (five versions listed); that page''s Anexo node did not load, so whether any amendment altered Anexo 2.5 is UNVERIFIED. Portugal has no JurisdictionCode value (jurisdiction_db_vocabulary class, left to the owner and not yet decided). Lead-in of 2.5.1: ''As rampas devem ter a menor inclinação possível''.', '2026-10-01 03:38', 'session_2026-10-01-research-batch-23', '2026-10-01 03:38', 'session_2026-10-01-research-batch-23', 'condition', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (112, 'REF-01022', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'NL', NULL, 'qualitative', 'supports adjusting the ramp (hellingbaan) requirements to align with draft NEN 9120; hopes other parts of the regulation follow once the standard is finished', NULL, 'De eisen voor hellingbanen worden aangepast zodat ze in lijn zijn met de NEN- norm 9120 die in ontwikkeling is. Ieder(in) ondersteunt de implementatie van deze NEN-norm', 'Letter p. 1, third bullet', NULL, 'committee_assertion', 'REF-01022', NULL, 'stated_unmeasured', 'not_device_scoped', 'Ieder(in) describes itself in the retrieved letter as ''het netwerk van mensen met een beperking of chronische ziekte'' -- people with any disability or chronic illness, not wheelchair users in particular. No individual authors or consulted members are named; the letter is signed by the director.', NULL, 0, NULL, 'section', NULL, NULL, 'Letter p. 1', NULL, 'bullet 3', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'A NATIONAL DISABILITY NETWORK''S ENDORSEMENT WITHOUT A FIGURE, FILED AS A FINDING (it asserts no value): the letter states no gradient and voices no criticism of the Bbl tiers. It is evidence that the network was consulted on, and supported, the ramp tiers Stb. 2024/368 (REF-01020) took from NEN 9120; it is NOT evidence that those tiers are acceptable to wheelchair users in use (contrast REF-01025, FUB 2007, which calls 1:12 a safety risk). RE-FILED after the adversarial pass (F1) as T3 grey with the same wording: Co-1 is not claimed because co-production is not evidenced in the retrieved bytes. Dated 9 November 2023, before the amendment was made (25 November 2024).', '2026-10-01 03:40', 'session_2026-10-01-research-batch-23', '2026-10-01 03:40', 'session_2026-10-01-research-batch-23', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (113, 'REF-01024', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'SE', NULL, 'numerical', '1:20', 'rise:run ratio (advised maximum between landings at least 2 m long; at most 0.5 m rise between landings)', 'En ramp bör a) luta högst 1:20 mellan minst 2 meter långa vilplan, b) ha en höjdskillnad på högst 0,5 meter mellan vilplanen', 'BFS 2011:5 ALM 2, 9 §, Allmänt råd (PDF p. 4)', NULL, 'committee_assertion', 'REF-01024', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, 'section', NULL, NULL, '9 §', 'Allmänt råd', 'a', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'GENERAL ADVICE (allmänt råd), NOT A BINDING FÖRESKRIFT: ''bör'' (should). Scope: public places and areas for facilities other than buildings (ALM 2, 1 §). Currency: Boverket''s own PBL-kunskapsbanken page on accessibility on public places, retrieved this session (artefact 54cbad3421ee4f37.html), names BFS 2011:5 - ALM 2 as the applicable regulation. Year: title page ''Utkom från trycket den 26 april 2011''. FILED T5 national_fw, NOT T6 code (adversarial finding F2): the instrument mixes binding föreskrifter and non-binding allmänna råd, and BOTH figures extracted from it are allmänna råd; governance/tier-system.md line 21 names ''Boverket BBR advisories'' as the T5 worked example. The binding föreskrift beside the 1:20 advice (9 §, first paragraph) states no gradient.', '2026-10-01 03:40', 'session_2026-10-01-research-batch-23', '2026-10-01 03:40', 'session_2026-10-01-research-batch-23', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (114, 'REF-01024', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'SE', 'kerb ramp (utjämning till 0-nivå)', 'numerical', '1:12', 'rise:run ratio (advised maximum for an utjämning till 0-nivå, a kerb-type levelling ramp at crossings and similar places)', 'En utjämning till 0-nivå bör inte ha större lutning än 1:12. Bredden bör vara 90–100 cm.', 'BFS 2011:5 ALM 2, 8 §, Allmänt råd (PDF p. 4)', NULL, 'committee_assertion', 'REF-01024', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, 'section', NULL, NULL, '8 §', 'Allmänt råd', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'GENERAL ADVICE (''bör''); the element is a dropped-kerb type ramp (utjämning till 0-nivå) between walking surfaces, not a ramp of travel, hence setting ''kerb ramp''. Currency: Boverket''s own PBL-kunskapsbanken page on accessibility on public places, retrieved this session (artefact 54cbad3421ee4f37.html), names BFS 2011:5 - ALM 2 as the applicable regulation. Year: title page ''Utkom från trycket den 26 april 2011''. FILED T5 national_fw, NOT T6 code (adversarial finding F2): the instrument mixes binding föreskrifter and non-binding allmänna råd, and BOTH figures extracted from it are allmänna råd; governance/tier-system.md line 21 names ''Boverket BBR advisories'' as the T5 worked example. The binding föreskrift beside the 1:20 advice (9 §, first paragraph) states no gradient.', '2026-10-01 03:40', 'session_2026-10-01-research-batch-23', '2026-10-01 03:40', 'session_2026-10-01-research-batch-23', 'claim', '<=');